replacements = [
  [ "accounting-officers", :law_content, "## 회계관계직원 등의 책임에 관한 법률 + 국고금관리법 + 지방회계법", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 지방회계법 제2조(정의)

  이 법에서 “중앙관서의 장”이란 다음 각 호의 어느 하나에 해당하는 사람을 말한다.
  1. 「헌법」이나 「정부조직법」 , 그 밖의 법률에 따라 설치된 중앙행정기관의 장
  2. 국회사무총장, 법원행정처장, 헌법재판소사무처장 및 중앙선거관리위원회사무총장

  ### 지방회계법 제4조(다른 법률과의 관계)

  지방자치단체의 일반회계ㆍ특별회계, 기금의 회계 및 결산에 관하여는 다른 법률에 특별한 규정이 있는 경우를 제외하고는 이 법에서 정하는 바에 따른다.

  ### 지방회계법 제22조(수납기관)

  ① 지방세와 그 밖의 세입은 그 수납을 담당하는 출납공무원(이하 “수입금출납원”이라 한다)이 아니면 수납할 수 없다. 다만, 지방자치단체에서 설치한 금고(교육비특별회계금고를 포함한다. 이하 같다) 또는 체신관서에 수납사무를 위탁하는 경우에는 그러하지 아니하다.

  ② 수입금출납원이 지방세와 그 밖의 세입을 직접 수납할 때에는 지체 없이 그 수납금을 해당 지방자치단체의 금고에 납입하여야 한다.

  ### 지방회계법 제21조(세입의 징수기관과 징수의 방법)

  ① 지방세와 그 밖의 세입의 징수는 지방자치단체의 장이 하되, 소속 공무원에게 위임하여 징수하게 할 수 있다.

  ② 지방자치단체의 장이나 그 위임을 받은 공무원(이하 “징수관”이라 한다)이 지방세와 그 밖의 세입을 징수할 때에는 징수 원인과 징수 금액을 조사ㆍ결정한 후 납부의무자에게 납입 고지를 하여야 한다.

  ### 지방회계법 제27조(지난 회계연도 수입과 지출금의 반납)

  ① 출납이 완결된 회계연도에 속하는 수입 또는 예산 외의 수입은 모두 현 회계연도의 세입에 편입하여야 한다.

  ② 세출로서 지출된 금액을 제7조에 따른 출납 폐쇄기한이 지나지 아니한 때에 반납하는 경우에는 지출한 세출의 해당 과목에 반납하여야 한다.

  ### 지방회계법 제46조(회계관계공무원의 임명 또는 위임)

  징수관ㆍ재무관ㆍ재산관리관ㆍ물품관리관ㆍ채권관리관ㆍ부채관리관ㆍ지출원 또는 출납원과 그 대리인ㆍ분임자(分任者) 등(이하 “회계관계공무원”이라 한다)의 임명 또는 위임은 지방자치단체의 장이 소속 기관에 설치된 직위를 지정하는 것으로 갈음할 수 있다.

  ### 지방회계법 제44조(출납원)

  ① 출납원은 지방자치단체의 장이나 그 위임을 받은 공무원이 소속 공무원 중에서 임명한다.

  ② 출납원은 법령, 조례 및 규칙에서 정하는 바에 따라 현금이나 물품을 출납ㆍ보관하여야 한다.

  ③ 출납원은 수입대체경비 출납원, 수입금출납원, 일상경비등 출납원, 세입세출외현금 출납원 및 물품 출납원 등으로 구분한다.

  ### 지방회계법 제36조(지출기관과 출납기관의 분리)

  재무관ㆍ지출원 및 현금출납의 직무는 서로 겸할 수 없다. 다만, 대통령령으로 정하는 경우에는 그러하지 아니하다.

  ### 지방회계법 제49조(회계관계공무원의 책임)

  회계관계공무원의 책임에 관하여는 「회계관계직원 등의 책임에 관한 법률」에서 정하는 바에 따른다.

  > 원문: 국가법령정보센터(law.go.kr) 지방회계법 [시행일 2026.01.02] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
