  ### 지방회계법 제35조(선금급과 개산급)

  지출원은 운임, 용선료(傭船料), 여비(旅費), 그 밖에 대통령령으로 정하는 경비로서 그 성질상 선금으로 또는 개괄산정하여 지급하지 아니하면 사무 또는 사업에 지장을 줄 우려가 있는 경우에는 선금급(先金給)이나 개산급(槪算給)으로 지급할 수 있다.

  > 원문: 국가법령정보센터(law.go.kr) 지방회계법 [시행일 2026.01.02] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
