  [ "annual-leave", :decree_content, "## 국가공무원 복무규정 제15조 (연가일수)", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 국가공무원 복무규정 제15조(연가 일수)

  ① 공무원의 재직기간별 연가 일수는 다음과 같다. 다만, 법 제28조 제2항 제2호 ㆍ제3호 및 제10호에 따라 임용된 경력직공무원 및 특수경력직공무원의 재직기간이 5년 미만이면서 인사혁신처장이 정하는 공무원 경력 외의 유사경력이 있는 경우에는 5년 미만의 재직기간별 연가 일수에 각각 3일을 더한다.

  ② 제1항에서 “재직기간”이란 「공무원연금법」 제25조 제1항부터 제3항까지의 규정에 따르되, 연월일수(年月日數)로 계산한 재직기간을 말하며, 휴직기간, 정직기간, 직위해제기간 및 강등 처분에 따라 직무에 종사하지 못하는 기간은 산입(算入)하지 아니한다. 다만, 다음 각 호의 휴직기간은 재직기간에 산입한다.
  1. 법 제71조 제2항 제4호의 사유에 따른 휴직으로 「공무원임용령」 제31조 제2항 제1호 다목에 따른 휴직기간
  2. 법령에 따른 의무 수행으로 인한 휴직
  3. 「공무원 재해보상법」에 따른 공무상 질병 또는 부상으로 인한 휴직

  ③ 연도 중 결근ㆍ휴직(법 제71조 제1항 제1호에 따른 휴직 중 공무상 질병 또는 부상으로 인한 휴직은 제외한다)ㆍ정직ㆍ강등ㆍ직위해제된 사실 및 인사혁신처장이 정하는 사실상 직무에 종사하지 않은 기간이 없는 공무원으로서 다음 각 호의 어느 하나에 해당하는 공무원에 대해서는 다음 해에만 제1항의 재직기간별 연가 일수에 각각 1일을 더한다.
  1. 병가(제18조 제2항에 따른 병가는 제외한다)를 받지 않은 공무원
  2. 제16조 제5항에 따른 연가보상비를 받지 못한 연가 일수가 남아 있는 공무원

  ### 국가공무원 복무규정 제16조(연가계획 및 승인)

  ① 행정기관의 장은 소속 공무원이 자유롭게 연가를 사용하여 심신을 새롭게 하고 공ㆍ사(公ㆍ私) 생활의 만족도를 높여 직무 생산성을 높일 수 있도록 특정한 계절에 치우치지 아니하게 연가계획을 수립하여 실시하여야 한다.

  ③ 연가는 오전 또는 오후의 반일(半日) 단위로 승인할 수 있으며, 반일 연가 2회는 연가 1일로 계산한다.

  ④ 행정기관의 장은 연가 신청을 받았을 때에는 공무 수행에 특별한 지장이 없으면 승인하여야 한다.

  ⑤ 공무상 연가를 승인할 수 없거나 해당 공무원이 연가를 활용하지 아니한 경우에는 예산의 범위에서 연가 일수(제11조 제4항에 따라 전환된 연가는 제외하되, 인사혁신처장이 정하는 사유에 해당하는 경우에는 포함한다. 이하 이 항에서 같다)에 해당하는 연가보상비를 지급하는 것으로 연가를 갈음할 수 있다. 이 경우 연가보상비를 지급할 수 있는 연가대상 일수는 20일을 초과할 수 없다.

  ⑥ 행정기관의 장은 소속 공무원에게 제15조 제1항에 따른 연가 일수가 없거나 재직기간별 연가 일수를 초과하는 휴가 사유가 발생한 경우에는 제15조 제1항에 따른 재직기간 구분 중 그 다음 재직기간의 연가 일수를 다음 표에 따라 미리 사용하게 할 수 있다.

  > 원문: 국가법령정보센터(law.go.kr) 국가공무원 복무규정 [시행일 2026.06.23] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
