  [ "bidding", :decree_content, "## 지방계약법 시행령 — 입찰 관련 조항", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 지방계약법 시행령 제13조(입찰의 참가자격)

  ① 지방자치단체의 장 또는 계약담당자는 다음 각 호의 요건을 갖춘 자만을 입찰에 참가하게 하여야 한다.
  1. 다른 법령에 따라 허가ㆍ인가ㆍ면허ㆍ등록ㆍ신고 등을 필요로 하거나 자격요건을 갖추어야 할 경우에는 해당 허가ㆍ인가ㆍ면허 등을 받았거나 등록ㆍ신고 등을 하였거나 해당 자격요건에 적합할 것
  2. 보안측정 등의 조사가 필요한 경우에는 관계 기관으로부터 적합판정을 받을 것
  3. 그 밖에 행정안전부령으로 정하는 요건에 적합할 것

  ② 「중소기업협동조합법」에 따른 중소기업협동조합이 물품의 제조 및 구매에 관한 입찰에 참가하는 경우로서 제1항제1호에 따른 요건을 갖춘 조합원으로 하여금 해당 물품을 제조하거나 구매하게 하는 경우에는 제1항제1호를 적용하지 아니한다.

  ### 지방계약법 시행령 제22조(지명입찰에 의할 계약)

  지방자치단체의 장 또는 계약담당자는 다음 각 호의 어느 하나에 해당하는 경우에는 법 제9조 제1항 단서에 따른 지명입찰에 부칠 수 있다.
  1. 계약의 성질 또는 목적에 비추어 특수한 설비ㆍ기술ㆍ자재ㆍ물품 또는 실적이 있는 자가 아니면 계약의 목적을 달성하기 곤란한 경우로서 입찰대상자가 10인 이내인 경우
  2. 「건설산업기본법」에 따른 종합공사의 경우 추정가격이 3억원(「건설산업기본법」에 따른 전문공사, 「전기공사업법」에 따른 전기공사, 「정보통신공사업법」에 따른 정보통신공사, 「소방시설공사업법」에 따른 소방시설공사, 그 밖의 공사 관련 법령에 따른 공사의 경우에는 1억원) 이하인 공사를 하거나 추정가격이 1억원 이하인 물품의 제조ㆍ구매 계약 또는 추정가격이 2억원 이하인 용역계약을 체결하려는 경우
  3. 추정가격이 5천만원 이하인 재산을 매입하는 경우
  4. 예정임차료의 연액(年額)(보증금이 있는 경우 보증금을 연 임대료로 환산한 금액을 포함한다)이 5천만원 이하인 재산이나 물품을 임차하는 경우
  5. 제1호부터 제4호까지의 규정 외의 계약으로서 추정가격이 5천만원 이하인 경우
  6. 「산업표준화법」 제15조에 따라 인증을 받은 제품, 같은 법 제25조에 따른 우수한 단체표준제품 또는 「녹색제품 구매촉진에 관한 법률」 제2조의2 제2호의 제품
  7. 법 제9조 제1항 단서, 이 영 제25조 제1항 및 같은 조 제3항에 따라 수의계약에 의할 수 있는 경우
  8. 「자원의 절약과 재활용촉진에 관한 법률」 제33조에 따른 기준에 적합하고, 「산업기술혁신 촉진법 시행령」 제17조 제1항 제3호에 따라 품질인증을 받은 재활용제품 또는 「환경기술 및 환경산업 지원법」 제17조에 따른 환경표지의 인증을 받은 제품을 제조하게 하거나 구매하는 경우
  9. 제79조 제1항 제2호에 따른 단가계약을 체결하려는 경우
  10. 「중소기업제품 구매촉진 및 판로지원에 관한 법률」 제6조에 따라 중소벤처기업부장관이 지정ㆍ공고한 물품을 「중소기업기본법」 제2조에 따른 중소기업자로부터 제조ㆍ구매하는 경우
  11. 「재난안전산업 진흥법」 제14조에 따라 지정된 재난안전신기술을 활용한 물품을 제조하게 하거나 구매하는 경우
  12. 「중소기업제품 구매촉진 및 판로지원에 관한 법률」 제7조의2 제2항 제2호에 따라 지방자치단체의 장의 요청으로 「중소기업협동조합법」 제3조에 따른 중소기업협동조합이 추천하는 소기업 또는 소상공인(해당 물품 등을 납품할 수 있는 소기업 또는 소상공인을 말한다)으로부터 물품 또는 용역을 제조하게 하거나 구매하는 경우

  ### 지방계약법 시행령 제12조(입찰의 성립)

  입찰은 입찰참가자격이 있는 자 2인 이상의 유효한 입찰로 성립한다.

