  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 지방회계법 제29조(지출원인행위)

  ① 지방자치단체의 지출 원인이 되는 계약이나 그 밖의 행위(이하 “지출원인행위”라 한다)는 지방자치단체의 장이 하되, 소속 공무원에게 위임하여 지출원인행위를 하게 할 수 있다.

  ② 지방자치단체의 장이나 그 위임을 받은 공무원(이하 “재무관”이라 한다)이 지출원인행위를 할 때에는 법령, 조례 및 규칙에서 정하는 바에 따라 배정된 예산의 범위에서 하여야 한다. 다만, 다른 법률에 별도의 규정이 있는 경우에는 그러하지 아니하다.

  > 원문: 국가법령정보센터(law.go.kr) 지방회계법 [시행일 2026.01.02] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
  MD
  [ "completion-payment-checklist", :decree_content, "## 지방계약법 시행령 제64조 (검사 기한)", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 지방계약법 시행령 제64조(검사)

  ① 법 제17조 제1항에 따른 검사는 계약상대자로부터 해당 계약의 이행을 완료한 사실을 통지받은 날부터 14일(「재난 및 안전관리 기본법」 제3조 제1호에 따른 재난이나 경기침체, 대량실업 등으로 인한 국가 또는 해당 지역의 경제위기를 극복하기 위해 행정안전부장관이 기간을 정하여 고시한 경우에는 계약상대자로부터 해당 계약의 이행을 완료한 사실을 통지받은 날부터 7일) 이내에 완료해야 한다. 다만, 행정안전부장관이 정하는 경우에는 7일(본문에 따라 7일 이내에 검사를 완료해야 하는 경우에는 3일)의 범위에서 그 검사기간을 연장할 수 있다.

  ② 제1항에 따른 검사를 할 때 조사설계 용역계약인 경우에는 그 용역계약의 상대자가 조사설계대상사업의 총사업비를 적정하게 산정하였는지를 함께 검사하여야 한다.

  ③ 기본설계(타당성 조사에 관한 내용을 포함한다. 이하 같다)와 실시설계를 구분하여 계약을 체결한 경우에는 제1항에 따라 실시설계용역에 대한 이행검사를 할 때에 실시설계 대상사업의 총사업비 산정이 적정한지를 기본설계서상의 총사업비와 실시설계서상의 총사업비를 비교하여 검사하여야 한다. 이 경우 기본설계서상의 총사업비와 실시설계서상의 총사업비에 차이가 있는 경우에는 실시설계용역의 계약상대자에게 그 사유를 설명하는 자료를 제출하게 하여야 한다.

  ④ 천재지변 등 불가항력의 사유로 제1항에 따른 기간 내에 검사를 완료하지 못한 경우에는 그 사유가 소멸된 날부터 3일 이내에 검사를 완료하여야 한다.

  ⑤ 지방자치단체의 장, 계약담당자 또는 법 제17조 제1항에 따라 검사를 위임받은 자는 제1항에 따른 검사를 할 때 계약상대자의 계약이행내용의 전부 또는 일부가 계약에 위반되거나 부당함을 발견하였을 때에는 지체 없이 필요한 시정조치를 명하여야 한다. 이 경우 계약상대자로부터 그 시정을 완료한 사실을 통지받은 날부터 제1항에 따른 기간을 계산한다.

  ⑥ 제67조 제3항에 따른 기성대가 지급 시의 기성검사는 법 제16조에 따른 감독을 하는 자가 작성한 감독조서의 확인으로 갈음할 수 있다. 다만, 그 검사 3회마다 1회는 법 제17조에 따른 검사를 실시하여야 한다.

  ### 지방계약법 시행령 제67조(대가의 지급)

  ① 법 제18조 제2항에 따라 지방자치단체의 재정부담이 되는 계약의 대가는 제64조에 따른 검사를 완료한 후 계약상대자의 청구를 받은 날부터 5일(「재난 및 안전관리 기본법」 제3조 제1호에 따른 재난이나 경기침체, 대량실업 등으로 인한 국가 또는 해당 지역의 경제위기를 극복하기 위해 행정안전부장관이 기간을 정하여 고시한 경우에는 계약상대자의 청구를 받은 날부터 3일을 말하며, 공휴일과 토요일은 제외한다. 이하 이 조에서 같다) 이내에 지급하여야 한다. 이 경우 계약당사자와 합의하여 5일을 초과하지 않는 범위에서 대가의 지급기한을 연장할 수 있는 특약을 정할 수 있다.

  ② 천재지변 등 불가항력의 사유로 지급기한까지 대가를 지급할 수 없게 된 경우에는 그 사유가 소멸된 날부터 3일 이내에 대가를 지급하여야 한다.

  ③ 법 제18조에 따라 기성 부분 또는 기납(旣納) 부분에 대한 대가를 지급하는 경우에는 제1항에도 불구하고 계약수량, 이행의 전망 및 이행기간 등을 고려하여 적어도 30일마다 지급하여야 한다.

  ④ 제3항에 따른 대가 지급 시에는 제64조에 따른 검사를 완료하는 날 이전까지 계약상대자에게 대가 지급 청구를 하게 할 수 있으며, 검사 완료일부터 5일 이내에 검사 내용에 따라 대가를 확정하여 지급하여야 한다. 다만, 계약상대자가 검사 완료일 후에 대가의 지급을 청구하였을 때에는 그 청구를 받은 날부터 5일 이내에 지급하여야 한다.

  ⑤ 지방자치단체의 장 또는 계약담당자는 제1항과 제4항에 따른 대가 지급의 청구를 받은 후 그 청구내용의 전부 또는 일부가 부당함을 발견하였을 때에는 그 사유를 명시하여 계약상대자에게 해당 청구서를 반송할 수 있다. 이 경우 반송한 날부터 재청구를 받은 날까지의 기간은 제1항 또는 제4항의 지급기간에 산입(算入)하지 아니한다.

  ⑥ 지방자치단체의 장 또는 계약담당자는 계약상대자가 상당한 기간 동안 대가의 지급 청구를 하지 아니하고 소속 근로자에게 임금을 지급하지도 아니하는 경우에는 해당 근로자의 청구에 따라 계약의 대가 중 근로자에게 지급될 임금을 직접 지급할 수 있도록 하는 내용을 계약서에 포함시킬 수 있다.

  ### 지방계약법 시행령 제68조(대가 지급 지연에 대한 이자)

  지방자치단체의 장 또는 계약담당자는 대금 지급 청구를 받은 경우에 제67조에 따른 대가 지급기한(지방자치단체 채무부담의 원인이 되는 계약체결인 경우에는 다음 회계연도 시작 후 「지방재정법」에 따라 해당 예산이 배정된 날부터 20일)까지 대가를 지급하지 못하는 경우에는 법 제18조 제2항에 따라 다음 계산식으로 산출한 금액을 이자로 지급하여야 한다. {지급기한의 다음 날부터 지급하는 날까지의 일수 × 해당 미지급금액 × 「지방회계법」 제38조에 따라 지방자치단체의 장이 지정한 금고의 일반자금 대출 시 적용되는 연체이자율}

  > 원문: 국가법령정보센터(law.go.kr) 지방계약법 시행령 [시행일 2026.06.03] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
  MD
  [ "contingency-fund", :decree_content, "## 지방재정법 시행령 — 예비비 사용 요건", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 지방재정법 시행령 제48조(예비비 사용의 제한)

  업무추진비ㆍ보조금(긴급재난대책을 위한 보조금을 제외한다)에 대하여는 법 제43조의 규정에 의한 예비비의 계상을 할 수 없다.

  > 원문: 국가법령정보센터(law.go.kr) 지방재정법 시행령 [시행일 2026.01.02] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
