  [ "contract-amount-adjustment", :law_content, "## 지방계약법 시행령 제74조 (계약금액 조정)", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 지방계약법 시행령 제74조(설계 변경으로 인한 계약금액의 조정)

  ① 지방자치단체의 장 또는 계약담당자는 공사계약에서 설계 변경으로 인하여 공사량의 증감이 발생하였을 때에는 법 제22조 제1항에 따라 해당 계약금액을 조정한다.

  ② 입찰참가자가 제15조 제7항 제1호 나목 또는 같은 항 제2호에 따라 물량내역서를 직접 작성하여 산출내역서를 제출하는 공사의 경우에는 입찰참가자가 직접 작성한 부분(제15조 제7항 제1호 나목의 경우에는 발주기관이 수정을 허용하였으나 입찰참가자가 수정하지 아니한 부분을 포함한다)에 누락ㆍ오류 등이 있어 계약내용을 변경하더라도 계약금액을 증액할 수 없다.

  ③ 계약담당자는 예정가격의 100분의 86 미만으로 낙찰된 공사계약의 계약금액을 제1항에 따라 증액 조정하려는 경우로서 해당 증액 조정금액(2차 이후의 계약금액을 조정할 때에는 그 전에 설계 변경으로 인하여 감액 또는 증액 조정된 금액과 증액 조정하려는 금액을 모두 합한 금액을 말한다)이 원래 계약금액의 100분의 10 이상인 경우에는 해당 지방자치단체의 장의 승인을 받아야 한다.

  ④ 제1항에 따라 계약금액을 조정할 때에는 다음 각 호의 기준에 따른다.
  1. 증감된 공사량의 단가는 제15조 제6항 또는 제7항에 따라 제출한 산출내역서상의 단가(이하 “계약단가”라 한다)로 한다. 다만, 계약단가가 제10조에 따른 예정가격의 단가(이하 “예정가격단가”라 한다)보다 높은 경우로서 물량이 증가하게 되는 경우 그 증가된 물량에 대한 적용단가는 예정가격단가로 한다.
  2. 계약단가가 없는 신규비목의 단가는 설계 변경 당시를 기준으로 하여 산정한 단가에 낙찰률을 곱한 금액으로 한다.
  3. 지방자치단체에서 설계 변경을 요구한 경우(계약상대자에게 책임이 없는 사유로 인한 경우를 포함한다)에는 제1호와 제2호에도 불구하고 증가된 물량 또는 신규비목의 단가는 설계 변경 당시를 기준으로 하여 산정한 단가와 그 단가에 낙찰률을 곱한 금액의 범위에서 계약당사자 간에 협의하여 결정한다. 다만, 계약당사자 간에 협의가 이루어지지 아니하는 경우에는 다음 계산식에 따라 계산한 금액으로 한다. [설계 변경 당시를 기준으로 하여 산정한 단가 + (설계 변경 당시를 기준으로 하여 산정한 단가 × 낙찰률)] × 50/100

  ⑤ 지방자치단체의 장 또는 계약담당자는 계약상대자가 새로운 기술ㆍ공법 등(지방자치단체의 설계와 같은 수준 이상의 기능ㆍ효과를 가진 기술ㆍ공법ㆍ기자재 등을 포함한다. 이하 같다)을 사용함으로써 공사비의 절감, 시공기간의 단축 등에 효과가 현저할 것으로 인정되어 계약상대자의 요청에 의하여 필요한 설계 변경을 하였을 때에는 그 절감액의 100분의 30에 해당하는 금액을 감액하여 계약금액을 조정한다.

  ⑥ 제5항의 경우 새로운 기술ㆍ공법 등의 범위와 한계에 관하여 이의가 있을 때에는 「건설기술 진흥법 시행령」 제19조에 따른 기술자문위원회(이하 “기술자문위원회”라 한다)에 청구하여 심의를 받아야 한다. 다만, 기술자문위원회가 설치되어 있지 아니한 경우에는 「건설기술 진흥법」 제5조에 따른 지방건설기술심의위원회(이하 “지방건설기술심의위원회”라 한다)의 심의를 받아야 한다.

  ⑦ 계약금액의 증감분에 대한 일반관리비 및 이윤 등은 제15조 제6항 또는 제7항에 따라 제출한 산출내역서상의 일반관리비율 및 이윤율 등에 의하여 산출하되 행정안전부령으로 정하는 비율을 초과할 수 없다.

  ⑧ 지방자치단체의 장 또는 계약담당자는 제1항에 따라 계약금액을 증액 조정할 때에는 행정안전부장관이 정하는 바에 따라 그 적절성과 적법성을 심사하여야 한다.

  ⑨ 제조ㆍ용역 등의 계약에서 계약금액을 조정하는 경우에는 제1항부터 제8항까지의 규정을 준용할 수 있다.

  > 원문: 국가법령정보센터(law.go.kr) 지방계약법 시행령 [시행일 2026.06.03] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
  MD
  [ "contract-execution", :decree_content, "## 지방계약법 시행령 — 계약 체결 관련 조항", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 지방계약법 시행령 제49조(계약서의 작성)

  법 제14조 제1항에 따라 지방자치단체의 장 또는 계약담당자가 작성하는 계약서의 서식과 그 밖에 필요한 사항은 행정안전부령으로 정한다.

  ### 지방계약법 시행령 제50조(계약서 작성의 생략 등)

  ① 법 제14조 제1항 단서에 따라 계약서의 작성을 생략할 수 있는 경우는 다음 각 호와 같다.
  1. 계약금액이 5천만원 이하인 계약을 체결하는 경우
  2. 경매에 부치는 경우
  3. 물품을 매각할 때 매수인이 즉시 대금을 내고 그 물품을 인수하는 경우
  4. 국가기관과 계약을 체결하거나 다른 지방자치단체와 계약을 체결하는 경우
  5. 전기ㆍ가스ㆍ수도의 공급계약 등 그 계약의 성질상 계약서를 작성할 필요가 없는 경우

  ② 법 제14조 제2항에서 “천재지변 등 대통령령으로 정하는 경우”란 천재지변ㆍ전산장애 또는 그 밖의 부득이한 사유로 정보처리장치를 이용할 수 없는 경우를 말한다.

  > 원문: 국가법령정보센터(law.go.kr) 지방계약법 시행령 [시행일 2026.06.03] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
  MD
  [ "contract-guarantee-deposit", :decree_content, "## 지방계약법 시행령 — 보증금 관련 조항", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 지방계약법 시행령 제52조(계약보증금 납부방법)

  ① 계약보증금은 현금 또는 제37조 제2항 각 호에 규정된 보증서 등으로 내게 하여야 한다.

  ② 「자본시장과 금융투자에 관한 법률 시행령」 제192조제2항에 따른 상장증권 또는 현금으로 납부된 계약보증금을 계약상대자가 특별한 사유로 제37조 제2항 제1호부터 제5호까지에 규정된 보증서 등으로 대체 납부할 것을 요청한 경우에는 그 가치에 상당하는 금액 이상으로 대체 납부하게 할 수 있다.

  ### 지방계약법 시행령 제53조(계약보증금 면제)

  ① 법 제15조 제1항 단서에 따라 계약보증금을 면제할 수 있는 경우는 다음 각 호와 같다.
  1. 제37조 제3항 제1호부터 제5호까지 및 제6호의2에 규정된 자와 계약을 체결하는 경우
  2. 계약금액이 5천만원 이하인 계약을 체결하는 경우
  3. 일반적으로 공정ㆍ타당하다고 인정되는 계약의 관습에 따라 계약보증금 징수가 적합하지 아니한 경우
  4. 이미 도입된 외국자본시설ㆍ기계ㆍ장비의 부분품을 구매하는 경우로서 해당 공급자가 아니면 그 부분품의 구입이 곤란한 경우

  ② 지방자치단체의 장 또는 계약담당자는 제1항에 따라 계약보증금의 납부를 면제받은 자에게 법 제15조 제3항에 따른 계약보증금의 세입조치 사유가 발생한 경우 계약보증금에 해당하는 금액을 낼 것을 보장하기 위하여 그 지급을 확약하는 내용의 문서(이하 이 조에서 “확약서”라 한다)를 제출하게 하여야 한다. 다만, 제1항제3호에 해당하는 경우에는 확약서 제출을 생략하게 할 수 있다.

  ### 지방계약법 시행령 제54조(계약보증금의 세입조치)

  ① 지방자치단체의 장 또는 계약담당자는 계약상대자가 정당한 이유 없이 계약상의 의무를 이행하지 아니하면 제51조에 따른 계약보증금을 법 제15조 제3항에 따라 지방자치단체에 세입조치하여야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 해당 호에서 정하는 금액을 제외한 금액을 세입조치 해야 한다.
  1. 성질상 분할할 수 있는 공사ㆍ물품 또는 용역 등에 관한 계약(법 제25조에 따른 단가계약은 제외한다)으로서 기성 부분 또는 기납 부분에 대한 검사를 거쳐 인수하거나 관리ㆍ사용하고 있는 경우: 당초의 계약보증금 중 기성 부분 또는 기납 부분에 해당하는 금액
  2. 법 제25조에 따른 단가계약으로서 여러 차례 분할하여 계약을 이행하는 경우: 당초의 계약보증금 중 이행이 완료된 부분에 해당하는 금액

  ② 장기계속계약에서 계약상대자가 제78조 제2항 후단과 같은 조 제3항에 따른 2차 이후의 공사 또는 제조 등의 계약을 체결하지 아니한 경우에는 제1항을 준용한다.

  ③ 제1항과 제2항에 따라 계약보증금을 지방자치단체에 세입조치할 때 그 계약보증금은 기성(旣成) 부분에 대한 미지급액과 상계(相計) 처리해서는 아니 된다. 다만, 제53조에 따라 계약보증금이 면제되는 경우에는 그러하지 아니하다.

  ④ 계약보증금을 세입조치할 경우에는 제38조를 준용한다.

  ### 지방계약법 시행령 제71조(하자보수보증금)

  ① 법 제21조에 따른 하자보수보증금은 행정안전부령으로 정하는 바에 따라 계약금액의 100분의 2 이상 100분의 10 이하로 하여야 한다. 다만, 계약의 성질상 하자보수가 필요하지 아니한 경우로서 행정안전부령으로 정하는 경우에는 하자보수보증금을 내지 아니하게 할 수 있다.

  ② 지방자치단체의 장 또는 계약담당자는 계약목적물에 대하여 제64조 제1항에 따른 검사를 완료한 때부터 계약의 대금을 지급하기 전까지 제1항에 따른 하자보수보증금을 내게 하고 이를 제69조에 따른 담보책임의 존속기간 동안 보관하여야 한다.

  ③ 장기계속계약의 경우에는 연차계약별로 대금을 지급하기 전까지 제1항 및 제2항에 따라 하자보수보증금을 내게 하여야 한다. 다만, 연차계약별로 하자담보책임을 구분할 수 없는 경우에는 전체 목적물에 대하여 제64조 제1항에 따른 검사를 완료하고 나서 하자보수보증금을 내게 하여야 한다.

  ④ 법 제21조 제1항 단서에 따라 하자보수보증금의 납부를 면제할 수 있는 경우는 다음 각 호와 같다.
  1. 제25조 제1항 제7호 나목에 따른 계약을 체결한 경우
  2. 제37조 제3항 제1호부터 제5호까지에 규정된 자와 계약을 체결한 경우

  ⑤ 하자보수보증금의 납부 및 지방자치단체 세입조치의 경우에는 제37조 제2항 ㆍ제4항 및 제38조를 준용한다.

  > 원문: 국가법령정보센터(law.go.kr) 지방계약법 시행령 [시행일 2026.06.03] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
  MD
  [ "contract-guarantee-exemption", :law_content, "## 지방계약법 제15조 (계약보증금)", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 지방계약법 제15조(계약보증금)

  ① 지방자치단체의 장 또는 계약담당자는 지방자치단체와 계약을 체결하려는 자로 하여금 계약보증금을 내도록 하여야 한다. 다만, 다른 지방자치단체, 공공기관 및 지방공기업 등 대통령령으로 정하는 계약상대자에 대하여는 계약보증금의 납부를 면제할 수 있다.

  ② 제1항에 따른 계약보증금의 금액ㆍ납부방법, 그 밖에 필요한 사항은 대통령령으로 정한다.

  ③ 지방자치단체의 장 또는 계약담당자는 계약상대자가 계약상의 의무를 이행하지 아니하면 그 계약보증금을 해당 지방자치단체에 귀속시켜야 한다. 다만, 제1항 단서에 따라 계약보증금의 납부를 면제한 경우에는 대통령령으로 정하는 바에 따라 계약상대자로 하여금 계약보증금에 해당하는 금액을 해당 지방자치단체에 내도록 하여야 한다.

  > 원문: 국가법령정보센터(law.go.kr) 지방계약법 [시행일 2024.02.17] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
  MD
  [ "contract-period-extension", :decree_content, "## 지방계약법 시행령 제75조의2 (계약기간 연장에 따른 계약금액의 조정)", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 지방계약법 시행령 제75조의2(계약기간 연장에 따른 계약금액의 조정)

  ① 법 제22조 제2항에서 “대통령령으로 정하는 계약상대자의 통제범위를 벗어난 사유”란 다음 각 호의 어느 하나에 해당하는 사유를 말한다.
  1. 호우, 해일, 대설, 한파, 가뭄, 폭염, 황사, 조류(藻類) 대발생, 조수(潮水), 화산활동, 그 밖에 이에 준하는 자연현상
  2. 붕괴, 폭발, 화생방사고ㆍ환경오염사고, 에너지ㆍ통신ㆍ교통ㆍ금융ㆍ의료ㆍ수도 등 국가기반체계의 마비, 「감염병의 예방 및 관리에 관한 법률」에 따른 감염병 또는 「가축전염병 예방법」에 따른 가축전염병의 확산, 「미세먼지 저감 및 관리에 관한 특별법」에 따른 고농도 미세먼지 비상저감조치의 시행
  3. 전쟁, 사변, 테러 또는 폭동
  4. 그 밖에 계약상대자의 통제범위를 벗어난 사유로서 행정안전부장관이 정하여 고시하는 사유

  ② 법 제22조 제2항에 따라 계약금액을 조정하는 경우에는 제74조 제7항을 준용한다.

  > 원문: 국가법령정보센터(law.go.kr) 지방계약법 시행령 [시행일 2026.06.03] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
  MD
  [ "cost-calculation-guide", :rule_content, "## 지방계약법 시행규칙 제4조 (예정가격조서의 작성)", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 지방계약법 시행규칙 제4조(예정가격조서의 작성)

  지방자치단체의 장 또는 계약담당자는 영 제10조에 따라 예정가격을 결정하려는 경우에는 미리 예정가격조서를 작성하여야 한다.

  > 원문: 국가법령정보센터(law.go.kr) 지방계약법 시행규칙 [시행일 2026.07.01] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
  MD
  [ "defect-warranty", :decree_content, "## 지방계약법 시행령 — 하자보수 관련 조항", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 지방계약법 시행령 제69조(담보책임의 존속기간)

  ① 법 제20조 제1항에 따른 공사의 도급계약에 대한 담보책임의 존속기간은 전체 목적물을 인수한 날과 제64조 제1항에 따른 검사를 완료한 날 중에서 먼저 도래한 날(공사계약의 부분 완료로 관리ㆍ사용이 이루어지고 있는 경우에는 부분 목적물을 인수한 날과 공고에 따라 관리ㆍ사용을 개시한 날 중에서 먼저 도래한 날을 말한다)부터 1년 이상 10년 이하의 범위에서 행정안전부령으로 정하는 기간으로 한다. 다만, 공사의 성질상 하자보수가 필요하지 아니한 경우로서 행정안전부령으로 정하는 경우에는 그러하지 아니하다.

  ② 법 제20조 제2항에 따른 물품 및 용역 등의 계약에 대한 담보책임의 존속기간은 전체 목적물을 인수한 날과 제64조 제1항에 따른 검사를 완료한 날 중에서 먼저 도래한 날부터 목적물의 성질에 따라 하자담보가 필요한 기간으로 한다.

  ③ 장기계속계약에 대한 담보책임의 존속기간은 연차계약별로 제1항 및 제2항에 따른 담보책임의 존속기간으로 한다. 다만, 연차계약별로 담보책임을 구분할 수 없는 경우에는 제1차 계약을 체결할 때에 전체 계약목적물에 대하여 정한다.

  ### 지방계약법 시행령 제70조(하자 검사)

  ① 지방자치단체의 장 또는 계약담당자는 제69조에 따른 담보책임의 존속기간 중 연 2회 이상 정기적으로 하자를 검사하거나 소속 공무원에게 그 사무를 위임하여 검사하게 하여야 한다.

  ② 지방자치단체의 장 또는 계약담당자는 다음 각 호의 어느 하나에 해당하는 경우에는 전문기관에 의뢰하여 필요한 검사를 하여야 한다.
  1. 제1항에 따른 하자 검사에 전문적인 지식 또는 기술을 필요로 하는 경우
  2. 제71조의3에 따른 하자보수에 필요한 금액의 산정이 전문적인 지식 또는 기술을 필요로 하는 경우
  3. 예정가격의 100분의 86 미만으로 낙찰된 공사로서 「시설물의 안전 및 유지관리에 관한 특별법」 제2조 제1호에 따른 시설물에 대한 공사인 경우

  ③ 제1항 및 제2항에 따라 하자를 검사하는 자는 하자검사조서를 작성하여야 한다. 다만, 계약금액이 3천만원 이하인 계약의 경우에는 하자검사조서의 작성을 생략할 수 있다.

  ### 지방계약법 시행령 제71조(하자보수보증금)

  ① 법 제21조에 따른 하자보수보증금은 행정안전부령으로 정하는 바에 따라 계약금액의 100분의 2 이상 100분의 10 이하로 하여야 한다. 다만, 계약의 성질상 하자보수가 필요하지 아니한 경우로서 행정안전부령으로 정하는 경우에는 하자보수보증금을 내지 아니하게 할 수 있다.

  ② 지방자치단체의 장 또는 계약담당자는 계약목적물에 대하여 제64조 제1항에 따른 검사를 완료한 때부터 계약의 대금을 지급하기 전까지 제1항에 따른 하자보수보증금을 내게 하고 이를 제69조에 따른 담보책임의 존속기간 동안 보관하여야 한다.

  ③ 장기계속계약의 경우에는 연차계약별로 대금을 지급하기 전까지 제1항 및 제2항에 따라 하자보수보증금을 내게 하여야 한다. 다만, 연차계약별로 하자담보책임을 구분할 수 없는 경우에는 전체 목적물에 대하여 제64조 제1항에 따른 검사를 완료하고 나서 하자보수보증금을 내게 하여야 한다.

  ④ 법 제21조 제1항 단서에 따라 하자보수보증금의 납부를 면제할 수 있는 경우는 다음 각 호와 같다.
  1. 제25조 제1항 제7호 나목에 따른 계약을 체결한 경우
  2. 제37조 제3항 제1호부터 제5호까지에 규정된 자와 계약을 체결한 경우

  ⑤ 하자보수보증금의 납부 및 지방자치단체 세입조치의 경우에는 제37조 제2항 ㆍ제4항 및 제38조를 준용한다.

  ### 지방계약법 시행령 제72조(하자보수보증금의 직접사용)

  ① 법 제21조 제4항에 따라 하자보수보증금을 해당 하자의 보수를 위하여 직접 사용하려는 경우에는 그 하자보수보증금을 세입으로 납입하지 아니하고 세입ㆍ세출 외로 구분하여 회계 처리한다.

  ② 제1항에 따른 하자보수보증금의 직접사용에 관한 절차는 행정안전부령으로 정한다.

  > 원문: 국가법령정보센터(law.go.kr) 지방계약법 시행령 [시행일 2026.06.03] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
  MD
  [ "design-change", :decree_content, "## 지방계약법 시행령 — 설계변경 관련 조항", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 지방계약법 시행령 제74조(설계 변경으로 인한 계약금액의 조정)

  ① 지방자치단체의 장 또는 계약담당자는 공사계약에서 설계 변경으로 인하여 공사량의 증감이 발생하였을 때에는 법 제22조 제1항에 따라 해당 계약금액을 조정한다.

  ② 입찰참가자가 제15조 제7항 제1호 나목 또는 같은 항 제2호에 따라 물량내역서를 직접 작성하여 산출내역서를 제출하는 공사의 경우에는 입찰참가자가 직접 작성한 부분(제15조 제7항 제1호 나목의 경우에는 발주기관이 수정을 허용하였으나 입찰참가자가 수정하지 아니한 부분을 포함한다)에 누락ㆍ오류 등이 있어 계약내용을 변경하더라도 계약금액을 증액할 수 없다.

  ③ 계약담당자는 예정가격의 100분의 86 미만으로 낙찰된 공사계약의 계약금액을 제1항에 따라 증액 조정하려는 경우로서 해당 증액 조정금액(2차 이후의 계약금액을 조정할 때에는 그 전에 설계 변경으로 인하여 감액 또는 증액 조정된 금액과 증액 조정하려는 금액을 모두 합한 금액을 말한다)이 원래 계약금액의 100분의 10 이상인 경우에는 해당 지방자치단체의 장의 승인을 받아야 한다.

  ④ 제1항에 따라 계약금액을 조정할 때에는 다음 각 호의 기준에 따른다.
  1. 증감된 공사량의 단가는 제15조 제6항 또는 제7항에 따라 제출한 산출내역서상의 단가(이하 “계약단가”라 한다)로 한다. 다만, 계약단가가 제10조에 따른 예정가격의 단가(이하 “예정가격단가”라 한다)보다 높은 경우로서 물량이 증가하게 되는 경우 그 증가된 물량에 대한 적용단가는 예정가격단가로 한다.
  2. 계약단가가 없는 신규비목의 단가는 설계 변경 당시를 기준으로 하여 산정한 단가에 낙찰률을 곱한 금액으로 한다.
  3. 지방자치단체에서 설계 변경을 요구한 경우(계약상대자에게 책임이 없는 사유로 인한 경우를 포함한다)에는 제1호와 제2호에도 불구하고 증가된 물량 또는 신규비목의 단가는 설계 변경 당시를 기준으로 하여 산정한 단가와 그 단가에 낙찰률을 곱한 금액의 범위에서 계약당사자 간에 협의하여 결정한다. 다만, 계약당사자 간에 협의가 이루어지지 아니하는 경우에는 다음 계산식에 따라 계산한 금액으로 한다. [설계 변경 당시를 기준으로 하여 산정한 단가 + (설계 변경 당시를 기준으로 하여 산정한 단가 × 낙찰률)] × 50/100

  ⑤ 지방자치단체의 장 또는 계약담당자는 계약상대자가 새로운 기술ㆍ공법 등(지방자치단체의 설계와 같은 수준 이상의 기능ㆍ효과를 가진 기술ㆍ공법ㆍ기자재 등을 포함한다. 이하 같다)을 사용함으로써 공사비의 절감, 시공기간의 단축 등에 효과가 현저할 것으로 인정되어 계약상대자의 요청에 의하여 필요한 설계 변경을 하였을 때에는 그 절감액의 100분의 30에 해당하는 금액을 감액하여 계약금액을 조정한다.

  ⑥ 제5항의 경우 새로운 기술ㆍ공법 등의 범위와 한계에 관하여 이의가 있을 때에는 「건설기술 진흥법 시행령」 제19조에 따른 기술자문위원회(이하 “기술자문위원회”라 한다)에 청구하여 심의를 받아야 한다. 다만, 기술자문위원회가 설치되어 있지 아니한 경우에는 「건설기술 진흥법」 제5조에 따른 지방건설기술심의위원회(이하 “지방건설기술심의위원회”라 한다)의 심의를 받아야 한다.

  ⑦ 계약금액의 증감분에 대한 일반관리비 및 이윤 등은 제15조 제6항 또는 제7항에 따라 제출한 산출내역서상의 일반관리비율 및 이윤율 등에 의하여 산출하되 행정안전부령으로 정하는 비율을 초과할 수 없다.

  ⑧ 지방자치단체의 장 또는 계약담당자는 제1항에 따라 계약금액을 증액 조정할 때에는 행정안전부장관이 정하는 바에 따라 그 적절성과 적법성을 심사하여야 한다.

  ⑨ 제조ㆍ용역 등의 계약에서 계약금액을 조정하는 경우에는 제1항부터 제8항까지의 규정을 준용할 수 있다.

  > 원문: 국가법령정보센터(law.go.kr) 지방계약법 시행령 [시행일 2026.06.03] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
  MD
  [ "direct-production-confirm", :law_content, "## 중소기업제품 구매촉진 및 판로지원에 관한 법률 제12조", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 중소기업제품 구매촉진 및 판로지원에 관한 법률 제12조(공사용 자재의 직접구매 증대)

  ① 중소벤처기업부장관은 경쟁제품으로 지정된 공사용 자재의 구매를 늘리기 위하여 필요한 조치를 할 수 있다.

  ② 중소벤처기업부장관은 경쟁제품 중에서 공공기관이 발주하는 공사에 필요한 자재로서 공사의 품질과 효율성을 해치지 아니하는 범위에서 공공기관이 직접 구매하여 제공하기에 적합한 제품을 관계 중앙행정기관의 장과 협의하여 선정하고, 고시하여야 한다 .

  ③ 대통령령으로 정하는 규모 이상의 공사를 발주하려는 공공기관의 장은 제2항에 따라 중소벤처기업부장관이 고시한 제품의 직접구매 여부를 검토하여 직접구매를 할 수 있도록 필요한 조치를 하여야 한다. 다만, 중소벤처기업부장관이 관계 중앙행정기관의 장과 협의하여 직접구매를 이행할 수 없는 사유로 고시한 경우에는 그러하지 아니하다.

  > 원문: 국가법령정보센터(law.go.kr) 중소기업제품 구매촉진 및 판로지원에 관한 법률 [시행일 2026.07.01] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
  MD
