  [ "e-bidding", :law_content, "## 전자조달의 이용 및 촉진에 관한 법률 제2조 (정의)", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 전자조달의 이용 및 촉진에 관한 법률 제2조(정의)

  이 법에서 사용하는 용어의 뜻은 다음과 같다.
  1. “수요기관”이란 국가기관ㆍ지방자치단체 및 대통령령으로 정하는 공공단체를 말한다.
  2. “계약담당자”란 관계 법령에 따라 수요기관의 계약사무 처리를 위임 또는 위탁받은 자를 말한다.
  3. “조달업무”란 수요기관의 장에게 필요한 물자 또는 용역의 구매ㆍ공급에 관한 업무 및 시설공사 계약에 관한 업무를 말한다.
  4. “국가종합전자조달시스템”이란 제12조에 따라 조달청장이 조달업무를 전자적으로 처리하기 위하여 구축ㆍ운용하는 정보시스템을 말한다.
  5. “전자조달”이란 국가종합전자조달시스템을 이용 또는 활용하여 조달업무를 전자적으로 처리하는 것을 말한다.
  6. “전자조달이용자”란 제17조에 따라 국가종합전자조달시스템에 이용자등록을 한 자를 말한다.

  ### 전자조달의 이용 및 촉진에 관한 법률 제5조(조달업무의 전자적 처리)

  ① 수요기관의 장은 전자조달시스템을 이용 또는 활용하여 조달업무를 전자적으로 처리하도록 노력하여야 한다.

  ② 조달청장은 전자조달을 촉진하기 위한 시책을 마련하여야 한다.

  ### 전자조달의 이용 및 촉진에 관한 법률 제6조(경쟁입찰의 전자적 공고)

  ① 수요기관의 장 또는 계약담당자는 경쟁입찰을 전자적으로 처리하려는 경우에는 입찰에 관한 사항을 전자조달시스템을 통하여 공고하여야 한다.

  ② 제1항에 따른 공고의 방법 및 시기와 그 밖에 필요한 사항은 대통령령으로 정한다.

  ### 지방계약법 제14조(계약서의 작성 및 계약의 성립)

  ① 지방자치단체의 장 또는 계약담당자는 계약을 체결하려는 경우에는 계약의 목적, 계약금액, 이행기간, 계약보증금, 위험부담, 지연배상금(遲延賠償金), 그 밖에 필요한 사항을 명백히 적은 계약서를 작성하여야 한다. 다만, 대통령령으로 정하는 경우에는 계약서의 작성을 생략할 수 있다.

  ② 지방자치단체의 장 또는 계약담당자는 계약을 체결하려는 경우에는 천재지변 등 대통령령으로 정하는 경우를 제외하고는 행정안전부장관이 지정하는 정보처리장치를 이용하여 「전자서명법」 제2조 제1호에 따른 전자문서에 의한 계약서를 작성하여야 한다.

  ③ 제1항 본문에 따라 계약서를 작성하는 경우에는 그 지방자치단체의 장 또는 계약담당자와 계약상대자가 계약서에 기명ㆍ날인하거나 서명(「전자서명법」 제2조 제2호에 따른 전자서명을 포함한다. 이하 같다)함으로써 계약이 확정된다.

  > 원문: 국가법령정보센터(law.go.kr) 전자조달의 이용 및 촉진에 관한 법률 [시행일 2026.01.02] · 지방계약법 [시행일 2024.02.17] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
