  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 지방계약법 시행령 제39조(입찰서의 제출ㆍ접수 및 입찰의 무효)

  ① 지방자치단체의 장 또는 계약담당자는 입찰자가 입찰서를 제출하는 경우 지정정보처리장치를 이용하여 입찰서를 제출하게 해야 한다. 다만, 미리 행정안전부장관과 협의한 경우에는 지정정보처리장치 외에 지방자치단체의 장이 지정ㆍ고시한 정보처리장치를 이용하여 입찰서를 제출하게 할 수 있다.

  ② 지방자치단체의 장 또는 계약담당자는 제1항에도 불구하고 입찰공고에 표시한 장소와 일시에 입찰서를 직접 제출하게 할 수 있다. 다만, 필요하다고 인정되는 경우에는 우편 등으로 제출하게 할 수 있다.

  ③ 입찰자는 제출한 입찰서를 교환ㆍ변경 또는 취소하지 못한다. 다만, 행정안전부장관이 정하는 경우에는 그러하지 아니하다.

  ④ 제13조와 제20조에 따른 입찰참가의 자격이 없는 자가 참가한 입찰이나 그 밖에 행정안전부령으로 정하는 사유에 해당하는 입찰은 무효로 한다. 다만, 제88조 제1항에 따른 공동수급체가 구성된 경우 공동수급체의 일부 구성원에게 입찰무효 사유가 있더라도 해당 구성원을 제외한 공동수급체만으로 입찰참가적격을 갖출 수 있는 경우에는 입찰을 무효로 하지 아니한다.

  > 원문: 국가법령정보센터(law.go.kr) 지방계약법 시행령 [시행일 2026.06.03] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
