  [ "entertainment-expense-rules", :law_content, "## 지방재정법 제47조 / 국가재정법 제45조 (예산의 목적 외 사용금지)", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 지방재정법 제47조(예산의 목적 외 사용금지)

  지방자치단체의 장은 세출예산에서 정한 목적 외의 용도로 경비를 사용할 수 없다.

  ### 국가재정법 제45조(예산의 목적 외 사용금지)

  각 중앙관서의 장은 세출예산이 정한 목적 외에 경비를 사용할 수 없다.

  > 원문: 국가법령정보센터(law.go.kr) 지방재정법 [시행일 2026.07.01] · 국가재정법 [시행일 2026.09.11] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
  MD
  [ "estimated-price", :decree_content, "## 예정가격의 결정 (지방계약법 시행령·시행규칙)", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 지방계약법 시행령 제10조(예정가격의 결정기준)

  ① 지방자치단체의 장 또는 계약담당자는 다음 각 호의 가격을 기준으로 하여 예정가격을 결정하여야 한다.
  1. 적정한 거래가 형성된 경우에는 행정안전부령으로 정하는 거래실례가격(법령에 따라 가격이 결정된 경우에는 그 결정가격 범위에서의 거래실례가격)
  2. 신규개발품, 특수규격품 등을 사용한 특수한 물품ㆍ공사ㆍ용역 등 계약의 특수성으로 인하여 적정한 거래실례가격이 없는 경우에는 원가계산에 의한 가격. 이 경우 원가계산에 의한 가격은 계약의 목적이 되는 물품ㆍ공사ㆍ용역 등을 구성하는 재료비ㆍ노무비ㆍ경비와 일반관리비 및 이윤으로 계산한다.
  3. 공사의 경우 이미 수행한 공사의 종류별 시장거래가격 등을 토대로 산정한 표준시장단가로서 관계 중앙행정기관의 장이 인정한 가격
  4. 제1호부터 제3호까지에 따른 가격을 기준으로 할 수 없는 경우에는 감정가격, 유사한 물품ㆍ공사ㆍ용역 등의 거래실례가격 또는 견적가격

  ③ 지방자치단체의 장 또는 계약담당자는 예정가격을 결정할 때에는 행정안전부장관이 정하는 바에 따라 그 적절성과 적법성을 심사하여야 한다.

  ④ 제1항 및 제3항에서 규정한 사항 외에 예정가격의 결정에 필요한 사항은 행정안전부장관이 정한다 .

  ### 지방계약법 시행규칙 제5조(거래실례가격 및 표준시장단가에 따른 예정가격의 결정)

  ① 영 제10조 제1항 제1호에 따른 거래실례가격을 기준으로 예정가격을 결정할 때에는 다음 각 호의 어느 하나에 해당하는 가격에 따르되, 해당 거래실례가격에 제6조 제1항 제4호 및 제5호에 따른 일반관리비 및 이윤을 따로 가산해서는 아니 된다.
  1. 조달청장이 조사하여 통보한 가격
  2. 재정경제부장관이 정하는 기준에 적합한 전문가격조사기관으로서 재정경제부장관에게 등록한 기관이 조사하여 공표한 가격
  3. 지방자치단체의 장 또는 계약담당자가 2 이상의 사업자에 대하여 해당 물품의 거래실례를 직접 조사하여 확인한 가격

  ② 영 제10조 제1항 제3호에 따른 표준시장단가를 기준으로 예정가격을 결정할 때에는 이미 수행한 공사의 종류별 계약단가, 입찰단가 및 시공단가 등을 토대로 시장상황과 시공 상황을 고려하여 산정하되, 표준시장단가의 금액 적용 기준 및 그 밖의 필요한 사항은 행정안전부장관이 정한다 .

  ### 지방계약법 시행규칙 제4조(예정가격조서의 작성)

  지방자치단체의 장 또는 계약담당자는 영 제10조에 따라 예정가격을 결정하려는 경우에는 미리 예정가격조서를 작성하여야 한다.

