  ### 지방회계법 제44조(출납원)

  ① 출납원은 지방자치단체의 장이나 그 위임을 받은 공무원이 소속 공무원 중에서 임명한다.

  ② 출납원은 법령, 조례 및 규칙에서 정하는 바에 따라 현금이나 물품을 출납ㆍ보관하여야 한다.

  ③ 출납원은 수입대체경비 출납원, 수입금출납원, 일상경비등 출납원, 세입세출외현금 출납원 및 물품 출납원 등으로 구분한다.

