  ### 지방계약법 시행령 제90조(지연배상금)

  ① 지방자치단체의 장 또는 계약담당자는 법 제30조 제1항에 따라 계약상대자(국가기관과 지방자치단체를 제외한다)가 계약상의 의무를 지체하였을 때에는 지연배상금으로서 계약금액(장기계속공사계약ㆍ장기계속물품제조계약ㆍ장기계속용역계약의 경우에는 연차별 계약금액을 말한다. 이하 이 조에서 같다)에 행정안전부령으로 정하는 비율과 지체일수를 곱한 금액을 계약상대자로 하여금 현금으로 납부하게 하여야 한다. 이 경우 계약상대자의 책임 없는 사유로 계약이행이 지체되었다고 인정될 때에는 그 해당 일수를 지체일수에 포함하지 아니한다.

  ② 제1항의 경우 기성 부분 또는 기납 부분에 대하여 검사를 거쳐 이를 인수한 경우(인수하지 아니하고 관리ㆍ사용하고 있는 경우를 포함한다. 이하 이 조에서 같다)에는 그 부분에 상응하는 금액을 계약금액에서 뺀 금액을 기준으로 지연배상금을 계산하여야 한다. 이 경우 기성 부분 또는 기납 부분의 인수는 성질상 분할할 수 있는 공사ㆍ물품 또는 용역 등에 대한 완성부분으로서 인수하는 것으로 한정한다.

  ③ 제1항 및 제2항에 따라 납부할 지연배상금은 계약금액(제2항에 따라 기성 부분 또는 기납 부분에 대하여 검사를 거쳐 이를 인수한 경우에는 그 부분에 상당하는 금액을 계약금액에서 뺀 금액을 말한다)의 100분의 30을 한도로 한다.

  ④ 지방자치단체의 장 또는 계약담당자는 제88조 제1항에 따라 공동수급체의 구성원이 분담하여 계약을 이행하도록 한 공동계약을 체결한 경우로서 그 공동계약의 일부 구성원이 그가 분담하는 부분의 계약 이행을 지연하여 다른 구성원이 분담하여 이행하는 부분의 계약 이행도 불가피하게 지연된 경우에는 해당 계약의 지연을 직접 야기한 구성원으로 하여금 지연배상금을 납부하게 하여야 한다. 이 경우 전체 계약금액에서 해당 계약의 지연을 야기하지 아니한 구성원의 계약금액을 뺀 금액을 기준으로 지연배상금을 계산하여야 한다.

  > 원문: 국가법령정보센터(law.go.kr) 지방계약법 시행령 [시행일 2026.06.03] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
  MD
  [ "leave-of-absence", :law_content, "## 국가공무원법 제71조 (휴직) 및 제72조 (휴직 기간)", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 국가공무원법 제71조(휴직)

  ① 공무원이 다음 각 호의 어느 하나에 해당하면 임용권자는 본인의 의사에도 불구하고 휴직을 명하여야 한다.
  1. 신체ㆍ정신상의 장애로 장기 요양이 필요할 때
  2. 삭제
  3. 「병역법」에 따른 병역 복무를 마치기 위하여 징집 또는 소집된 때
  4. 천재지변이나 전시ㆍ사변, 그 밖의 사유로 생사(生死) 또는 소재(所在)가 불명확하게 된 때
  5. 그 밖에 법률의 규정에 따른 의무를 수행하기 위하여 직무를 이탈하게 된 때
  6. 「공무원의 노동조합 설립 및 운영 등에 관한 법률」 제7조에 따라 노동조합 전임자로 종사하게 된 때

  ② 임용권자는 공무원이 다음 각 호의 어느 하나에 해당하는 사유로 휴직을 원하면 휴직을 명할 수 있다. 다만, 제4호 및 제4호의2의 경우에는 대통령령으로 정하는 특별한 사정이 없으면 휴직을 명하여야 한다.
  1. 국제기구, 외국 기관, 국내외의 대학ㆍ연구기관, 다른 국가기관 또는 대통령령으로 정하는 민간기업, 그 밖의 기관에 임시로 채용될 때
  2. 국외 유학을 하게 된 때
  3. 중앙인사관장기관의 장이 지정하는 연구기관이나 교육기관 등에서 연수하게 된 때
  4. 12세 이하 또는 초등학교 6학년 이하의 자녀를 양육하기 위하여 필요하거나 여성공무원이 임신 또는 출산하게 된 때 4의2. 난임으로 인하여 대통령령으로 정하는 치료를 하게 된 때
  5. 조부모, 부모(배우자의 부모를 포함한다), 배우자, 자녀 또는 손자녀를 부양하거나 돌보기 위하여 필요한 경우. 다만, 조부모나 손자녀의 돌봄을 위하여 휴직할 수 있는 경우는 본인 외에 돌볼 사람이 없는 등 대통령령등으로 정하는 요건을 갖춘 경우로 한정한다.
  6. 외국에서 근무ㆍ유학 또는 연수하게 되는 배우자를 동반하게 된 때
  7. 대통령령등으로 정하는 기간 동안 재직한 공무원이 직무 관련 연구과제 수행 또는 자기개발을 위하여 학습ㆍ연구 등을 하게 된 때

  ③ 임기제공무원에 대하여는 제1항제1호ㆍ제3호 및 제2항제4호ㆍ제4호의2에 한정하여 제1항 및 제2항을 적용한다.

  ④ 임용권자는 제2항제4호 및 제4호의2에 따른 휴직을 이유로 인사에 불리한 처우를 하여서는 아니 된다.

  ⑤ 제1항부터 제4항까지의 규정에 따른 휴직 제도 운영에 관하여 필요한 사항은 대통령령등으로 정한다.

  ### 국가공무원법 제72조(휴직 기간)

  휴직 기간은 다음과 같다.
  1. 제71조제1항제1호에 따른 휴직기간은 1년 이내로 하되, 부득이한 경우 1년의 범위에서 연장할 수 있다. 다만, 다음 각 목의 어느 하나에 해당하는 공무상 질병 또는 부상으로 인한 휴직기간은 3년 이내로 하되, 의학적 소견 등을 고려하여 대통령령등으로 정하는 바에 따라 2년의 범위에서 연장할 수 있다.
     가. 「공무원 재해보상법」 제22조제1항에 따른 요양급여 지급 대상 부상 또는 질병
     나. 「산업재해보상보험법」 제40조에 따른 요양급여 결정 대상 질병 또는 부상
  2. 제71조제1항제3호와 제5호에 따른 휴직 기간은 그 복무 기간이 끝날 때까지로 한다.
  3. 제71조제1항제4호에 따른 휴직 기간은 3개월 이내로 한다.
  4. 제71조제2항제1호에 따른 휴직 기간은 그 채용 기간으로 한다. 다만, 민간기업이나 그 밖의 기관에 채용되면 3년 이내로 한다.
  5. 제71조제2항제2호와 제6호에 따른 휴직 기간은 3년 이내로 하되, 부득이한 경우에는 2년의 범위에서 연장할 수 있다.
  6. 제71조제2항제3호에 따른 휴직 기간은 2년 이내로 한다.
  7. 제71조제2항제4호에 따른 휴직 기간은 자녀 1명에 대하여 3년 이내로 한다. 7의2. 제71조제2항제4호의2에 따른 휴직 기간은 1년 이내로 하되, 부득이한 경우 1년의 범위에서 연장할 수 있다.
  8. 제71조제2항제5호에 따른 휴직 기간은 1년 이내로 하되, 재직 기간 중 총 3년을 넘을 수 없다.
  9. 제71조제1항제6호에 따른 휴직 기간은 그 전임 기간으로 한다.
  10. 제71조제2항제7호에 따른 휴직 기간은 1년 이내로 한다.

  > 원문: 국가법령정보센터(law.go.kr) 국가공무원법 [시행일 2026.06.02] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
