  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 공무원수당 등에 관한 규정 제11조의3(육아휴직수당)

  ① 「국가공무원법」 제71조 제2항 제4호에 따른 사유로 30일 이상 휴직한 공무원의 육아휴직수당은 육아휴직 시작일부터 6개월째까지는 육아휴직 시작일을 기준으로 한 월봉급액에 해당하는 금액으로 하고, 7개월째 이후는 육아휴직 시작일을 기준으로 한 월봉급액의 80퍼센트에 해당하는 금액으로 한다. 이 경우 육아휴직수당의 월별 지급액의 상한액은 다음 각 호의 구분에 따라 산정하되, 월별 지급액이 70만원보다 적은 경우에는 70만원으로 한다.
  1. 육아휴직 시작일부터 3개월째까지: 250만원
  2. 육아휴직 4개월째부터 6개월째까지: 200만원
  3. 육아휴직 7개월째 이후: 160만원

  ② 제1항에도 불구하고 다음 각 호의 어느 하나에 해당하는 공무원이 육아휴직을 한 경우에는 육아휴직수당을 다음 각 호의 구분에 따른 금액으로 한다.
  1. 같은 자녀에 대하여 부모가 모두 육아휴직을 한 경우로서 두 번째 육아휴직을 한 사람이 공무원인 경우 해당 공무원: 다음 각 목의 구분에 따라 산정한 금액
     가. 육아휴직 시작일부터 6개월째까지: 육아휴직 시작일을 기준으로 한 월봉급액에 해당하는 금액. 이 경우 그 상한액은 2개월째까지는 250만원, 3개월째는 300만원, 4개월째는 350만원, 5개월째는 400만원, 6개월째는 450만원으로 한다.
     나. 육아휴직 7개월째부터 12개월째(제7항 각 호의 어느 하나에 해당하는 경우에는 18개월째)까지: 제1항에 따른 금액
  2. 「한부모가족지원법」에 따른 모 또는 부에 해당하는 공무원: 다음 각 목의 구분에 따라 산정한 금액
     가. 육아휴직 시작일부터 3개월째까지: 육아휴직 시작일을 기준으로 한 월봉급액에 해당하는 금액. 이 경우 그 상한액은 300만원으로 한다.
     나. 육아휴직 4개월째부터 12개월째(제7항 각 호의 어느 하나에 해당하는 경우에는 18개월째)까지: 제1항에 따른 금액
     다. 삭제

  ⑤ 육아휴직 대상자가 육아휴직을 대신하거나 9세 이상 12세 이하의 자녀 또는 초등학교 3학년 이상 6학년 이하의 자녀를 양육하기 위하여 「공무원임용령」 제57조의3 제2항에 따른 시간선택제전환공무원으로 지정된 경우에는 다음의 계산식에 따라 산정한 금액(이하 “육아기 근무시간 단축수당”이라 한다)을 지급한다. 다만, 육아기 근무시간 단축수당을 포함한 보수액이 해당 공무원이 전일제로 근무할 때에 받을 보수액을 초과하는 경우에는 그 차액을 빼고 지급한다.

  ⑥ 육아휴직수당 및 육아기 근무시간 단축수당의 지급기간은 휴직일 또는 지정일부터 최초 1년 이내로 한다. 다만, 각 수당의 지급기간을 합산하여 최대 1년을 초과할 수 없다.

  ⑦ 제6항에도 불구하고 다음 각 호의 어느 하나에 해당하는 공무원의 경우 육아휴직수당 및 육아기 근무시간 단축수당의 지급기간은 휴직일 또는 지정일부터 최초 18개월 이내로 하되, 각 수당의 지급기간을 합산하여 최대 18개월을 초과할 수 없다.
  1. 같은 자녀에 대하여 부모가 모두 육아휴직을 각각 3개월 이상 한 경우의 부 또는 모
  2. 「한부모가족지원법」에 따른 모 또는 부
  3. 인사혁신처장이 정하는 장애가 있는 자녀의 부 또는 모

  ⑧ 「국가공무원법」 제47조 제3항에 따라 각급 행정기관의 장은 소속 공무원이 거짓이나 그 밖의 부정한 방법으로 제1항 및 제2항에 따른 육아휴직수당 또는 제5항에 따른 육아기 근무시간 단축수당을 지급받은 경우에는 그 지급받은 수당에 해당하는 금액을 징수하여야 한다.

  ⑨ 육아휴직수당 및 육아기 근무시간 단축수당 지급방법 등 수당 지급에 필요한 사항은 인사혁신처장이 정한다 .

