  [ "private-contract-justification", :law_content, "## 지방계약법 제9조 (계약의 방법) · 시행령 제25조 (수의계약에 의할 수 있는 경우)", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 지방계약법 제9조(계약의 방법)

  ① 지방자치단체의 장 또는 계약담당자는 계약을 체결하려는 경우에는 이를 공고하여 일반입찰에 부쳐야 한다. 다만, 계약의 목적ㆍ성질ㆍ규모 및 지역특수성 등을 고려하여 필요하다고 인정되면 참가자를 지명(指名)하여 입찰에 부치거나 수의계약을 할 수 있다.

  ② 제1항 본문에 따라 일반입찰에 부치는 경우 대통령령으로 정하는 바에 따라 입찰 참가자격을 사전심사하여 적격자만을 입찰에 참가하게 하거나 시공능력, 실적, 기술보유상황, 법인등기부상 본점소재지(개인사업자인 경우에는 사업자등록증 또는 관련 법령에 따른 허가ㆍ인가ㆍ면허ㆍ등록ㆍ신고 등에 관련된 서류에 기재된 사업장의 소재지를 말한다. 이하 같다) 등으로 입찰 참가자격을 제한하여 입찰에 부칠 수 있다.

  ③ 제1항 단서에 따른 지명기준 및 지명절차, 수의계약의 대상범위 및 수의계약상대자의 선정절차, 그 밖에 필요한 사항은 대통령령으로 정한다.

  ④ 지방자치단체의 장 또는 계약담당자는 제1항 단서에 따라 수의계약을 체결한 경우 대통령령으로 정하는 바에 따라 수의계약 내용을 공개하여야 한다.

  ⑤ 제1항에 따라 계약을 체결하는 과정에서 다른 법률에 따른 우선구매 대상이 경합하는 경우에는 계약의 목적이나 규모, 사회적 약자에 대한 배려 수준 등을 고려하여 계약상대자를 결정하여야 한다.

  ### 지방계약법 시행령 제25조(수의계약에 의할 수 있는 경우)

  ① 지방자치단체의 장 또는 계약담당자는 다음 각 호의 어느 하나에 해당하는 경우에는 법 제9조 제1항 단서에 따라 수의계약을 할 수 있다.
  1. 천재지변, 감염병의 발생 및 유행, 작전상의 병력이동, 긴급한 행사, 원자재의 가격급등, 그 밖에 이에 준하는 경우로서 입찰에 부칠 여유가 없는 경우
  2. 입찰에 부칠 여유가 없는 긴급복구가 필요한 재난 등 행정안전부령에 따른 재난복구 등의 경우
  3. 국가기관, 다른 지방자치단체(「지방자치법」 제176조에 따른 지방자치단체조합을 포함한다)와 계약을 하는 경우
  4. 특정인의 기술ㆍ용역 또는 특정한 위치ㆍ구조ㆍ품질ㆍ성능ㆍ효율 등으로 인하여 경쟁을 할 수 없는 경우로서 다음 각 목의 경우
     가. 공사에서 장래 시설물의 하자에 대한 책임구분이 곤란한 경우로서 행정안전부장관이 정하는 기준에 적합한 직전 또는 현재의 시공자와 계약을 하는 경우
     나. 작업상의 혼잡 등으로 하나의 현장에서 2인 이상의 시공자가 공사를 할 수 없는 경우로서 행정안전부장관이 정하는 기준에 적합한 현재의 시공자와 계약을 하는 경우
     다. 마감공사에 대하여 행정안전부장관이 정하는 기준에 적합한 직전 또는 현재의 시공자와 계약을 하는 경우
     라. 접경지역 등 특수지역에서의 공사로서 사실상 경쟁이 불가능한 경우
     마. 특허공법, 「건설기술 진흥법」 제14조에 따라 지정ㆍ고시된 신기술, 「환경기술 및 환경산업 지원법」 제7조에 따라 인증받은 신기술 또는 「재난안전산업 진흥법」 제14조에 따라 지정된 재난안전신기술(각 해당 법률에 따라 지정된 보호기간 또는 유효기간 내의 경우로 한정한다)에 의한 공사로서 사실상 경쟁이 불가능한 경우
     바. 해당 물품을 제조ㆍ공급한 자가 직접 그 물품을 설치ㆍ조립(시험가동을 포함한다) 또는 정비하는 경우
     사. 특허를 받았거나 실용신안등록 또는 디자인등록이 된 물품을 제조하게 하거나 구매하는 경우로서 적절한 대용품이나 대체품이 없는 경우
     아. 해당 물품의 생산자나 소지자가 1인뿐인 경우로서 다른 물품을 제조하게 하거나 구매해서는 사업목적을 달성할 수 없는 경우
     자. 특정인의 기술ㆍ품질이나 경험ㆍ자격이 필요한 조사ㆍ설계ㆍ감리ㆍ특수측량ㆍ훈련ㆍ시설관리ㆍ교육ㆍ행사ㆍ정보이용ㆍ의상(의류)구매 계약을 체결하거나 관련 법령에 따라 디자인공모에 당선된 자와 설계용역 계약을 체결하는 경우
     차. 특정인과의 학술연구를 위한 용역계약을 할 필요가 있는 경우
     카. 특정인의 토지ㆍ건물 등 부동산을 매입하거나 특정인의 재산을 임차하는 경우
     타. 이미 조달된 물품 등의 부품교환 또는 설비확충 등을 위하여 조달하는 경우로서 해당 물품 등을 제조ㆍ공급한 자 외의 자로부터 제조ㆍ공급을 받게 되면 호환이 되지 아니하는 경우
     파. 특정한 장소나 위치에 있는 사업장을 보유한 자와 그 사업장의 이용과 관련한 계약을 체결하지 않으면 계약목적을 달성하기 곤란한 물품의 제조ㆍ구매 또는 용역 계약을 체결하는 경우
     하. 「매장유산 보호 및 조사에 관한 법률」 제11조에 따른 매장유산 발굴(조사)용역으로서 시공 중인 건설공사의 지연이 예상되는 등 긴급한 사유가 있거나 시굴(試掘)조사 후 정밀발굴조사로 전환되는 등 매장유산 발굴의 연속성 유지가 필요한 경우
  5. 다음 각 목의 어느 하나에 해당하는 계약
     가. 「건설산업기본법」에 따른 건설공사(같은 법에 따른 전문공사는 제외한다)로서 추정가격이 4억원 이하인 공사, 같은 법에 따른 전문공사로서 추정가격이 2억원 이하인 공사 및 그 밖의 공사 관련 법령에 따른 공사로서 추정가격이 1억6천만원 이하인 공사에 대한 계약
     나. 추정가격이 2천만원 이하인 물품의 제조ㆍ구매계약 또는 용역계약
     다. 추정가격이 2천만원 초과 5천만원 이하인 계약으로서 「중소기업창업 지원법」 제2조 제11호에 따른 청년창업기업과 체결하는 물품의 제조ㆍ구매계약 또는 용역계약
     라. 추정가격이 2천만원 초과 1억원 이하인 계약으로서 「중소기업기본법」 제2조 제2항에 따른 소기업 또는 「소상공인기본법」 제2조에 따른 소상공인과 체결하는 물품의 제조ㆍ구매계약 또는 용역계약. 다만, 제30조 제1항 제3호 및 같은 조 제2항 단서에 해당하는 경우에는 소기업 또는 소상공인 외의 자와 체결하는 물품의 제조ㆍ구매계약 또는 용역계약을 포함한다.
     마. 추정가격이 2천만원 초과 1억원 이하인 계약 중 학술연구ㆍ원가계산ㆍ건설기술 등과 관련된 계약으로서 특수한 지식ㆍ기술 또는 자격을 요구하는 물품의 제조ㆍ구매계약 또는 용역계약
     바. 추정가격이 2천만원 초과 1억원 이하인 계약으로서 다음의 어느 하나에 해당하는 기업 또는 조합과 체결하는 물품의 제조ㆍ구매계약 또는 용역계약. 다만, 3)부터 6)까지에 해당하는 기업 또는 조합의 경우에는 행정안전부장관이 정하여 고시하는 취약계층 고용비율을 충족하여야 한다. 1) 「여성기업지원에 관한 법률」 제2조 제1호에 따른 여성기업 2) 「장애인기업활동 촉진법」 제2조 제2호에 따른 장애인기업 3) 「사회적기업 육성법」 제2조 제1호에 따른 사회적기업 4) 「협동조합 기본법」 제2조 제3호에 따른 사회적협동조합 5) 「국민기초생활 보장법」 제18조에 따른 자활기업 6) 「도시재생 활성화 및 지원에 관한 특별법」 제2조 제1항 제9호에 따른 마을기업으로서 행정안전부장관이 정하는 기준에 적합한 기업
     사. 추정가격이 5천만원 이하인 임대차 계약(연액 또는 총액을 기준으로 추정가격을 산정한다) 등으로서 공사계약 또는 물품의 제조ㆍ구매계약이나 용역계약이 아닌 계약
  6. 다른 법률에 따라 특정사업자로 하여금 특수한 물품ㆍ재산 등을 매입하거나 제조하도록 하는 경우로서 다음 각 목의 경우
     가. 「방위사업법」에 따른 방산물자를 방위산업체로부터 제조ㆍ구매하는 경우
     나. 「농어촌정비법」에 따른 농공단지에 입주한 공장(새마을공장을 포함한다)이 직접 생산하는 물품을 이들로부터 제조ㆍ구매하는 경우
     다. 「지역중소기업 육성 및 혁신촉진에 관한 법률」에 따른 중소기업특별지원지역에 입주한 공장이 직접 생산하는 물품을 이들로부터 구매하는 경우
     라. 「중소기업진흥에 관한 법률」 제2조 제1호에 따른 중소기업자가 직접 생산한 다음의 어느 하나에 해당하는 제품을 그 생산자로부터 제조ㆍ구매하는 경우로서 주무부장관으로부터 인증 또는 지정된 유효기간(주무부장관이 인증 또는 지정된 유효기간을 연장한 경우에는 연장된 기간을 포함한다. 이하 이 목에서 같다) 이내에 해당하는 경우. 다만, 유효기간이 6년을 넘는 경우에는 6년으로 한다. 1) 「중소기업제품 구매촉진 및 판로지원에 관한 법률」 제15조에 따라 성능인증을 받은 제품 2) 「소프트웨어 진흥법」 제20조에 따라 품질인증을 받은 받은 제품 3) 「산업기술혁신 촉진법」 제16조에 따라 신제품으로 지정된 제품 4) 다음 법률의 규정에 따라 인증 또는 지정ㆍ고시된 신기술을 이용하여 제조한 제품으로서 주무부장관이 상용화 단계에서 성능을 확인한 제품 가) 「건설기술 진흥법」 제14조 나) 「국가통합교통체계효율화법」 제102조 다) 「농림식품과학기술 육성법」 제12조의2 라) 「농업기계화 촉진법」 제7조 마) 「목재의 지속가능한 이용에 관한 법률」 제18조 바) 「물류정책기본법」 제57조 사) 「보건의료기술 진흥법」 제8조 아) 「산업기술혁신 촉진법」 제15조의2 자) 「재난안전산업 진흥법」 제14조 차) 「해양수산과학기술 육성법」 제17조 카) 「환경기술 및 환경산업 지원법」 제7조 5) 「조달사업에 관한 법률 시행령」 제30조에 따라 우수조달물품으로 지정ㆍ고시된 제품 6) 「조달사업에 관한 법률 시행령」 제31조에 따라 지정ㆍ고시된 우수조달공동상표의 물품(「국가를 당사자로 하는 계약에 관한 법률 시행령」 제26조 제1항 제3호 바목에 따라 재정경제부장관이 고시한 금액 미만의 물품을 구매하는 경우에 한정한다) 7) 「중소기업 기술혁신 촉진법」 제9조 제1항 제3호에 따른 지원을 받아 개발이 완료된 제품으로서 당초의 수요와 연계된 자가 구매하기로 협약한 제품 8) 삭제 9) 「재난안전산업 진흥법」 제16조 제1항에 따른 적합성 인증을 받은 제품 10) 「기후위기 대응을 위한 탄소중립ㆍ녹색성장 기본법」 제60조 제2항에 따라 적합성 인증을 받은 녹색제품 11) 「물관리기술 발전 및 물산업 진흥에 관한 법률」 제10조 제1항에 따라 지정된 우수제품 12) 「산업융합 촉진법」 제13조 제1항에 따라 적합성 인증을 받은 산업융합 신제품
  7. 특정연고자, 지역주민 및 특정물품 생산자 등과 계약할 필요가 있거나 그 밖에 이에 준하는 사유가 있는 경우로서 다음 각 목의 경우
     가. 비상재해가 발생한 경우로서 지방자치단체가 소유하는 복구용 자재를 재해를 당한 자에게 매각하는 경우
     나. 지역사회의 개발을 위하여 그 지역주민의 다수를 참여시킬 필요가 있는 경우로서 추정가격이 2천만원 미만인 공사 또는 추정가격이 5천만원 미만인 묘목재배를 행정안전부령으로 정하는 그 지역의 주민 또는 대표자와 직접 계약하는 경우
     다. 국가보훈부장관이 지정하는 국가유공자 자활용사촌의 복지공장에서 직접 생산하는 물품을 그 생산자로부터 제조ㆍ구매하거나 이들에게 직접 물품을 매각 또는 임대하는 경우 7의2. 국가유공자 또는 장애인 등에게 일자리나 보훈ㆍ복지서비스 등을 제공하기 위한 경우로서 다음 각 목의 경우
     가. 「국가유공자 등 단체 설립에 관한 법률」 제1조에 따라 설립된 단체 중 상이(傷痍)를 입은 사람들로 구성된 단체가 직접 생산하는 물품의 제조ㆍ구매 또는 직접 수행하는 용역계약을 하거나 이들에게 직접 물품을 매각 또는 임대하는 경우
     나. 「중증장애인생산품 우선구매 특별법」 제9조 제1항에 따라 지정받은 중증장애인생산품 생산시설이 직접 생산하는 물품의 제조ㆍ구매 또는 직접 수행하는 용역계약을 하거나 이들에게 직접 물품을 매각 또는 임대하는 경우
     다. 「사회복지사업법」에 따라 설립된 법인이 직접 생산하는 물품의 제조ㆍ구매 또는 직접 수행하는 용역계약을 하거나 이들에게 직접 물품을 매각 또는 임대하는 경우
     라. 「장애인고용촉진 및 직업재활법」 제22조의4 제1항에 따라 인증을 받은 장애인 표준사업장이 직접 생산하는 물품의 제조ㆍ구매 또는 직접 수행하는 용역계약을 하거나 이들에게 직접 물품을 매각 또는 임대하는 경우
  8. 그 밖에 계약의 목적ㆍ성질 등에 비추어 경쟁에 따라 계약을 체결하는 것이 비효율적이라고 판단되는 경우로서 다음 각 목의 경우
     가. 지방자치단체의 해외사무소에서 사용하는 물품을 현지에서 구매하는 경우
     나. 물품의 가공ㆍ하역ㆍ운송 또는 보관을 하게 할 때 입찰에 부치는 것이 불리하다고 인정되는 경우
     다. 「조달사업에 관한 법률」 제27조 제1항에 따른 혁신제품을 구매하려는 경우
     라. 삭제
     마. 삭제
     바. 삭제
     사. 다른 법령에 따라 국가 또는 지방자치단체의 사업을 위탁받거나 대행할 수 있는 자와 해당 사업에 대한 계약을 하는 경우
     아. 시험지와 비밀문서의 인쇄 등 지방자치단체가 그 행위를 비밀리에 할 필요가 있는 경우
     자. 「과학기술기본법」 등 관련 법령에 따른 연구개발사업을 통해 개발된 제품 중 각 중앙행정기관의 장이 행정안전부장관과 협의하여 정한 기준과 절차에 따라 기술의 혁신성을 인정한 제품을 구매하려는 경우
     차. 「클라우드컴퓨팅 발전 및 이용자 보호에 관한 법률」 제20조 제3항에 따라 선정된 디지털서비스에 관한 계약을 하는 경우

  ② 지방자치단체의 장 또는 계약담당자는 제1항제6호나목, 같은 항 제7호다목 및 같은 항 제7호의2에 따라 수의계약을 하는 경우 다음 각 호의 사항을 확인하여야 한다.
  1. 수의계약대상자의 자격요건
  2. 수의계약대상 물품의 직접 생산 및 용역의 직접 수행 가능 여부

  > 원문: 국가법령정보센터(law.go.kr) 지방계약법 [시행일 2024.02.17] · 지방계약법 시행령 [시행일 2026.06.03] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
  MD
  [ "public-debt-management", :decree_content, "## 지방채 발행 절차 및 한도", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 지방재정법 시행령 제10조(지방채발행 한도액의 산정 등)

  ① 법 제11조 제2항에 따라 지방채는 총사업비가 다음 각 호의 구분에 따른 금액 미만일 때에는 발행할 수 없다. 다만, 청사정비기금을 차입하는 경우에는 그러하지 아니하다.
  1. 시ㆍ도가 시행하는 재정투자사업: 40억원
  2. 시ㆍ군 및 자치구가 시행하는 재정투자사업: 20억원

  ② 법 제11조 제2항에 따른 지방채발행 한도액은 다음 각 호의 사항을 고려하여 행정안전부장관이 정하는 지방채발행 한도액 산정기준에 따라 지방자치단체의 장이 해당 지방자치단체의 전전연도 예산액의 100분의 10의 범위에서 정하는 금액으로 한다.
  1. 법 제11조 제1항에 따라 발행한 지방채의 발행액
  2. 법 제13조의 규정에 의한 보증채무부담행위액 중 채무자의 파산 등으로 인하여 지방자치단체가 채무이행의 책임을 지게 된 금액
  3. 법 제44조의 규정에 의한 채무부담행위액
  4. 그 밖에 해당 지방자치단체의 채무규모, 채무상환일정, 재정부담상황 등 행정안전부장관이 정하는 사항

  ③ 특별시장ㆍ광역시장ㆍ특별자치시장ㆍ도지사 및 특별자치도지사(이하 “시ㆍ도지사”라 한다)는 제2항에도 불구하고 「경제자유구역의 지정 및 운영에 관한 특별법」 제27조의2 제1항에 따라 설치한 행정기구(같은 항 후단에 따른 공동 행정기구를 포함한다)의 원활한 사업추진을 위하여 필요한 경우에는 지방채발행 한도액을 추가로 정할 수 있다. 이 경우 추가로 정하는 지방채발행 한도액과 제2항에 따라 정한 지방채발행 한도액을 더한 금액은 해당 시ㆍ도의 전전연도 예산액의 100분의 10을 넘을 수 없다.

  > 원문: 국가법령정보센터(law.go.kr) 지방재정법 시행령 [시행일 2026.01.02] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
