  [ "public-procurement-overview", :law_content, "## 공공조달의 법적 정의와 근거", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 조달사업에 관한 법률 제1조(목적)

  이 법은 조달사업을 공정하고 효율적으로 수행하기 위하여 조달사업의 범위와 운영 및 관리에 필요한 사항을 규정함을 목적으로 한다.

  ### 조달사업에 관한 법률 제2조(정의)

  이 법에서 사용하는 용어의 뜻은 다음과 같다.
  1. “조달물자”란 수요물자와 비축물자(備蓄物資)를 말한다.
  2. “수요물자”란 수요기관에 필요한 물자로서 대통령령으로 정하는 물자를 말한다.
  3. “비축물자”란 장단기(長短期)의 원활한 물자수급과 물가안정, 재난ㆍ국가위기 등 비상시 대비를 위하여 정부가 단독으로 또는 정부와 민간이 협력하여 비축하거나 공급하는 원자재, 시설자재 및 생활필수품으로서 대통령령으로 정하는 물자를 말한다.
  4. “안전관리물자”란 국민의 생활안전, 생명보호, 보건위생과 관련된 조달물자로서 조달청장이 지정ㆍ고시하는 물자를 말한다.
  5. “수요기관”이란 조달물자, 공사 계약의 체결 또는 시설물의 관리가 필요한 다음 각 목의 기관을 말한다.
     가. 「국가재정법」 제6조에 따른 독립기관 및 중앙관서(이하 “국가기관”이라 한다)
     나. 「지방자치법」 제2조에 따른 지방자치단체(이하 “지방자치단체”라 한다)
     다. 그 밖에 대통령령으로 정하는 기관

  ### 국가계약법 제5조(계약의 원칙)

  ① 계약은 서로 대등한 입장에서 당사자의 합의에 따라 체결되어야 하며, 당사자는 계약의 내용을 신의성실의 원칙에 따라 이행하여야 한다.

  ② 각 중앙관서의 장 또는 계약담당공무원은 제4조 제1항에 따른 국제입찰의 경우에는 호혜(互惠)의 원칙에 따라 정부조달협정 가입국(加入國)의 국민과 이들 국가에서 생산되는 물품 또는 용역에 대하여 대한민국의 국민과 대한민국에서 생산되는 물품 또는 용역과 차별되는 특약(特約)이나 조건을 정하여서는 아니 된다.

  ③ 각 중앙관서의 장 또는 계약담당공무원은 계약을 체결할 때 이 법 및 관계 법령에 규정된 계약상대자의 계약상 이익을 부당하게 제한하는 특약 또는 조건(이하 “부당한 특약등”이라 한다)을 정해서는 아니 된다.

  ④ 제3항에 따른 부당한 특약등은 무효로 한다.

  ### 지방계약법 제6조(계약의 원칙)

  ① 계약은 상호 대등한 입장에서 당사자의 합의에 따라 체결되어야 하고, 당사자는 계약의 내용을 신의성실의 원칙에 따라 이행하여야 한다.

  ② 지방자치단체의 장 또는 계약담당자는 제5조 제1항에 따른 국제입찰의 경우에는 호혜(互惠)의 원칙에 따라 정부조달협정등에 가입한 국가의 국민과 이들 국가에서 생산되는 물품이나 용역에 대하여 대한민국의 국민과 대한민국에서 생산되는 물품이나 용역과 차별되는 특약이나 조건을 정하여서는 아니 된다.

  ③ 지방자치단체의 장 또는 계약담당자는 계약을 체결할 때 이 법 및 관계 법령에 규정된 계약상대자의 계약상 이익을 부당하게 제한하는 특약이나 조건(이하 “부당한 특약등”이라 한다)을 정하여서는 아니 되고, 부당한 특약등은 무효로 한다.

  > 원문: 국가법령정보센터(law.go.kr) 조달사업에 관한 법률 [시행일 2026.09.11] · 국가계약법 [시행일 2026.06.11] · 지방계약법 [시행일 2024.02.17] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
  MD
  [ "qualification-failure", :law_content, "## 지방계약법 제13조 (낙찰자 결정)", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 지방계약법 제13조(낙찰자 결정)

  ① 지방자치단체 수입의 원인이 되는 입찰에서는 최고가격의 입찰자를 낙찰자로 한다. 다만, 계약의 목적, 입찰가격 및 수량 등을 고려하여 대통령령으로 기준을 정한 경우에는 그에 따른다.

  ② 지방자치단체 재정지출의 부담이 되는 입찰에서는 다음 각 호의 어느 하나에 해당하는 입찰자를 낙찰자로 한다.
  1. 충분한 계약이행능력이 있다고 인정되는 자로서 최저가격으로 입찰한
     자. 다만, 입찰자 중 최저가격으로 입찰한 자의 순으로 입찰금액의 적정성을 심사하여 낙찰자를 결정할 수 있다.
  2. 입찰가격, 품질, 기술력, 제안서 내용, 계약기간 등을 종합적으로 고려하여 해당 지방자치단체에 가장 유리하게 입찰한 자
  3. 상징성, 기념성, 예술성 등의 창의성이 요구되는 설계용역을 할 때에는 설계공모에 당선된 자
  4. 그 밖에 계약의 성질ㆍ규모 등을 고려하여 대통령령으로 기준을 정한 경우에는 그 기준에 가장 맞게 입찰한 자

  ③ 제2항에 따른 적용대상, 낙찰자 선정기준 및 선정절차, 그 밖에 필요한 사항은 대통령령으로 정한다.

  ④ 지방자치단체의 장 또는 계약담당자는 제2항에도 불구하고 공사에 대한 경쟁입찰로서 예정가격이 100억원 미만인 공사의 경우 대통령령으로 정하는 바에 따라 산정한 다음 각 호에 해당하는 비용의 합계액의 100분의 98 미만으로 입찰한 자를 낙찰자로 하여서는 아니 된다.
  1. 재료비ㆍ노무비ㆍ경비
  2. 제1호에 대한 부가가치세

  > 원문: 국가법령정보센터(law.go.kr) 지방계약법 [시행일 2024.02.17] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
