  [ "reinstatement", :decree_content, "## 휴직 사유별 복직 처리 (공무원임용령 등)", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 지방공무원법 제65조(휴직의 효력)

  ① 휴직 중인 공무원은 공무원의 신분은 보유하나 직무에 종사하지 못한다.

  ② 휴직 중인 공무원은 휴직기간 중 그 사유가 소멸되면 30일 이내에 임용권자에게 신고하여야 하며, 임용권자는 지체 없이 복직을 명하여야 한다.

  ③ 휴직기간이 끝난 공무원이 30일 이내에 복귀신고를 하면 당연히 복직된다.

  ### 국가공무원법 제73조(휴직의 효력)

  ① 휴직 중인 공무원은 신분은 보유하나 직무에 종사하지 못한다.

  ② 휴직 기간 중 그 사유가 없어지면 30일 이내에 임용권자 또는 임용제청권자에게 신고하여야 하며, 임용권자는 지체 없이 복직을 명하여야 한다.

  ③ 휴직 기간이 끝난 공무원이 30일 이내에 복귀 신고를 하면 당연히 복직된다.

  ### 지방공무원법 제64조(휴직기간)

  휴직기간은 다음 각 호와 같다.
  1. 제63조제1항제1호에 따른 휴직기간은 1년 이내로 하되, 부득이한 경우 1년의 범위에서 연장할 수 있다. 다만, 다음 각 목의 어느 하나에 해당하는 질병 또는 부상으로 인한 휴직기간은 3년 이내로 하되, 의학적 소견 등을 고려하여 대통령령으로 정하는 바에 따라 2년의 범위에서 연장할 수 있다.
     가. 「공무원 재해보상법」 제22조제1항에 따른 요양급여 지급대상 부상 또는 질병
     나. 「산업재해보상보험법」 제40조에 따른 요양급여 결정 대상 질병 또는 부상
  2. 제63조제1항제2호 및 제5호에 따른 휴직기간은 복무기간이 끝날 때까지로 한다.
  3. 제63조제1항제3호에 따른 휴직기간은 3개월 이내로 한다.
  4. 제63조제1항제4호에 따른 휴직기간은 그 전임기간으로 한다.
  5. 제63조제2항제1호에 따른 휴직기간은 그 채용기간으로 한다. 다만, 민간기업이나 그 밖의 기관에 채용되는 경우에는 3년 이내로 한다.
  6. 제63조제2항제2호 및 제6호에 따른 휴직기간은 3년 이내로 하되, 부득이한 경우에는 2년의 범위에서 연장할 수 있다.
  7. 제63조제2항제3호에 따른 휴직기간은 2년 이내로 한다.
  8. 제63조제2항제4호에 따른 휴직기간은 자녀 1명에 대하여 3년 이내로 한다. 8의2. 제63조제2항제4호의2에 따른 휴직기간은 1년 이내로 하되, 부득이한 경우 1년의 범위에서 연장할 수 있다.
  9. 제63조제2항제5호에 따른 휴직기간은 1년 이내로 하되, 재직기간 중 총 3년을 초과할 수 없다.
  10. 제63조제2항제7호에 따른 휴직기간은 1년 이내로 한다.

  > 원문: 국가법령정보센터(law.go.kr) 지방공무원법 [시행일 2026.06.02] · 국가공무원법 [시행일 2026.06.02] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
  MD
