  [ "sick-leave", :decree_content, "## 국가공무원 복무규정 제18조 (병가)", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 국가공무원 복무규정 제18조(병가)

  ① 행정기관의 장은 소속 공무원이 다음 각 호의 어느 하나에 해당할 경우에는 연 60일의 범위에서 병가를 승인할 수 있다. 이 경우 질병이나 부상으로 인한 지각ㆍ조퇴 및 외출은 누계 8시간을 병가 1일로 계산하고, 제17조 제5항에 따라 연가 일수에서 빼는 병가는 병가 일수에 산입하지 아니한다.
  1. 질병 또는 부상으로 인하여 직무를 수행할 수 없을 때
  2. 감염병에 걸려 그 공무원의 출근이 다른 공무원의 건강에 영향을 미칠 우려가 있을 때

  ② 행정기관의 장은 소속 공무원이 공무상 질병 또는 부상으로 직무를 수행할 수 없거나 요양이 필요할 경우에는 연 180일의 범위에서 병가를 승인할 수 있다.

  ③ 병가 일수가 연간 6일을 초과하는 경우에는 의사의 진단서를 첨부하여야 한다.

  > 원문: 국가법령정보센터(law.go.kr) 국가공무원 복무규정 [시행일 2026.06.23] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
  MD
  [ "small-amount-contract", :rule_content, "## 소액수의계약 관련 규정 (지방계약법 시행령·집행기준)", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 지방계약법 시행령 제30조(수의계약대상자의 선정절차 등)

  ① 지방자치단체의 장 또는 계약담당자는 수의계약을 체결하려는 경우에는 2인 이상으로부터 견적서를 받아야 한다. 다만, 다음 각 호의 어느 하나에 해당하는 경우에는 1인으로부터 받은 견적서에 의할 수 있다.
  1. 제25조 제1항 각 호(제5호는 제외한다), 제26조 제1항 ㆍ제2항 및 제27조에 따른 계약의 경우
  2. 추정가격이 2천만원 이하인 공사, 물품의 제조ㆍ구매 및 용역의 경우. 다만, 다음 각 목의 어느 하나에 해당하는 기업 또는 조합과 계약을 체결하는 경우에는 추정가격이 5천만원 이하인 경우로 한다.
     가. 「중소기업창업 지원법」 제2조 제11호에 따른 청년창업기업, 「여성기업지원에 관한 법률」 제2조 제1호에 따른 여성기업 또는 「장애인기업활동 촉진법」 제2조 제2호에 따른 장애인기업
     나. 「사회적기업 육성법」 제2조 제1호에 따른 사회적기업, 「협동조합 기본법」 제2조 제3호에 따른 사회적협동조합, 「국민기초생활 보장법」 제18조에 따른 자활기업 또는 「도시재생 활성화 및 지원에 관한 특별법」 제2조 제1항 제9호에 따른 마을기업으로서 행정안전부장관이 정하는 기준에 적합한 기업. 이 경우에는 행정안전부장관이 정하여 고시하는 취약계층 고용비율을 충족하여야 한다.
  3. 제2항에 따라 지정정보처리장치를 이용하여 견적서를 제출받았으나 견적서 제출자가 1인뿐인 경우로서 다시 견적서를 제출받더라도 견적서 제출자가 1인뿐일 것으로 명백히 예상되는 경우

  ② 제1항 본문에 따라 2인 이상으로부터 견적서를 제출받는 경우 및 제26조 제2항에 따라 재공고 입찰을 실시하지 않고 수의계약을 체결할 수 있는 경우에는 지정정보처리장치를 이용해야 한다. 다만, 품질확인 및 예산절감의 필요성이 큰 경우 등 행정안전부장관이 정한 경우에는 지정정보처리장치를 이용하지 아니할 수 있다.

  ③ 제1항과 제2항에 따라 제출받은 견적서에 적힌 견적가격이 예정가격(제8조 제2항에 따라 예정가격 작성을 생략한 경우에는 추정가격에 부가가치세를 포함한 금액을 말한다)의 범위에 들지 아니하는 경우 등 계약상대자를 결정할 수 없을 때에는 다시 견적서를 제출받아 제5항에 따라 수의계약대상자를 결정한다.

  ④ 제1항부터 제3항까지의 규정에도 불구하고 행정안전부령으로 정하는 경우에는 견적서 제출을 생략하게 할 수 있다.

  ⑤ 지방자치단체의 장 또는 계약담당자는 견적제출자의 견적가격과 계약이행능력 등 행정안전부장관이 정하는 기준에 따라 수의계약대상자를 결정한다.

  ### 지방계약법 시행령 제53조(계약보증금 면제)

  ① 법 제15조 제1항 단서에 따라 계약보증금을 면제할 수 있는 경우는 다음 각 호와 같다.
  1. 제37조 제3항 제1호부터 제5호까지 및 제6호의2에 규정된 자와 계약을 체결하는 경우
  2. 계약금액이 5천만원 이하인 계약을 체결하는 경우
  3. 일반적으로 공정ㆍ타당하다고 인정되는 계약의 관습에 따라 계약보증금 징수가 적합하지 아니한 경우
  4. 이미 도입된 외국자본시설ㆍ기계ㆍ장비의 부분품을 구매하는 경우로서 해당 공급자가 아니면 그 부분품의 구입이 곤란한 경우

  ② 지방자치단체의 장 또는 계약담당자는 제1항에 따라 계약보증금의 납부를 면제받은 자에게 법 제15조 제3항에 따른 계약보증금의 세입조치 사유가 발생한 경우 계약보증금에 해당하는 금액을 낼 것을 보장하기 위하여 그 지급을 확약하는 내용의 문서(이하 이 조에서 “확약서”라 한다)를 제출하게 하여야 한다. 다만, 제1항제3호에 해당하는 경우에는 확약서 제출을 생략하게 할 수 있다.

  ### 지방계약법 시행령 제8조(예정가격의 작성 및 비치)

  ① 지방자치단체의 장 또는 계약담당자는 입찰이나 수의계약 등에 부칠 사항에 대하여 해당 규격서 및 설계서 등에 따라 예정가격을 작성하고 다음 각 호의 구분에 따라 이를 갖추어 두거나 입력하여야 하며 예정가격이 누설되지 아니하도록 하여야 한다. 다만, 공유재산의 매각 등 관련 법령에서 따로 정하는 경우는 그러하지 아니하다.
  1. 서면에 의한 입찰이나 수의계약의 경우: 작성된 예정가격을 밀봉하여 미리 개찰장소 또는 가격협상장소 등에 갖추어둘 것
  2. 지정정보처리장치를 통한 입찰이나 수의계약의 경우: 작성된 예정가격을 지정정보처리장치에 입력할 것

  ② 다음 각 호의 어느 하나에 해당하는 계약은 예정가격을 작성하지 아니할 수 있다. 다만, 제5호 및 제6호의 경우에는 예정가격을 작성하지 아니한다.
  1. 제25조 제1항 제3호 및 제5호에 따른 수의계약(제30조 제2항 본문에 따라 지정정보처리장치를 이용하여 견적서를 제출하게 하는 경우는 제외한다)
  2. 제43조 또는 제44조에 따른 협상에 의한 계약
  3. 제44조의2에 따른 경쟁적 대화에 의한 계약
  4. 제81조 또는 제82조에 따른 개산계약
  5. 제95조 제1항 제5호에 따른 일괄입찰
  6. 제127조 제3호에 따른 기본설계 기술제안입찰에 의한 계약

  ③ 지방자치단체의 장 또는 계약담당자는 제82조에 따른 개산계약을 입찰할 때 예정가격을 작성하려는 경우에는 표준설계도 등을 기초로 하여 계산한 예정가격(이하 “개산예정가격”이라 한다)을 작성하고 제1항 각 호의 구분에 따라 이를 갖추어두거나 입력하여야 하며 개산예정가격이 누설되지 아니하도록 하여야 한다.

  > 원문: 국가법령정보센터(law.go.kr) 지방계약법 시행령 [시행일 2026.06.03] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
  MD
  [ "supplementary-budget", :law_content, "## 지방재정법 제45조 (추가경정예산)", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 지방재정법 제45조(추가경정예산의 편성 등)

  지방자치단체의 장은 이미 성립된 예산을 변경할 필요가 있을 때에는 추가경정예산(追加更正豫算)을 편성할 수 있다. 다만, 다음 각 호의 경비는 추가경정예산의 성립 전에 사용할 수 있으며, 이는 같은 회계연도의 차기 추가경정예산에 계상하여야 한다.
  1. 시ㆍ도의 경우 국가로부터, 시ㆍ군 및 자치구의 경우 국가 또는 시ㆍ도로부터 그 용도가 지정되고 소요 전액이 교부된 경비
  2. 시ㆍ도의 경우 국가로부터, 시ㆍ군 및 자치구의 경우 국가 또는 시ㆍ도로부터 재난구호 및 복구와 관련하여 복구계획이 확정ㆍ통보된 경우 그 소요 경비

  > 원문: 국가법령정보센터(law.go.kr) 지방재정법 [시행일 2026.07.01] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
  MD
  [ "travel-expense-settlement", :decree_content, "## 여비정산 절차 및 서류 (공무원 여비 규정)", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 공무원 여비 규정 제5조(여행일수의 계산)

  여행일수는 여행을 위하여 실제로 필요한 일수에 의하여 계산한다. 다만, 공무의 형편상 또는 천재지변이나 그 밖의 부득이한 사유로 늘어나는 일수는 여행일수에 포함한다.

  ### 공무원 여비 규정 제4조(여비의 계산)

  여비는 일반적인 경로 및 방법에 의하여 계산한다. 다만, 공무의 형편상 또는 천재지변이나 그 밖의 부득이한 사유로 일반적인 경로 및 방법에 의한 여행을 하기 곤란한 경우에는 실제로 여행한 경로 및 방법에 의하여 계산한다.

  ### 공무원 여비 규정 제16조(일비ㆍ숙박비ㆍ식비의 지급)

  ① 국내 여행자의 일비(日費)ㆍ숙박비 및 식비는 별표 2에 따라 지급하고, 국외 여행자의 경우는 별표 4에 따라 지급한다. 다만, 공무의 형편이나 그 밖의 부득이한 사유로 숙박비의 상한액 및 지급받은 식비(국내 여행의 경우 식비는 제외한다)를 초과하여 여비를 지출하였을 때에는 국내 여행의 경우에는 숙박비 상한액의 10분의 3을, 국외 여행의 경우에는 숙박비 및 식비의 2분의 1을 넘지 아니하는 범위에서 여비를 추가로 지급할 수 있다.

  ② 제1항 단서에 따라 여비를 추가로 지급받으려는 공무원은 여행을 마친 날의 다음 날부터 기산하여 1주일 이내(국외 여행의 경우에는 2주일 이내를 말한다)에 정부구매카드 또는 신용카드를 사용하고 받은 매출전표에 세부 사용내용이 명시된 증거자료를 갖추어 회계 관계 공무원에게 정산을 신청하여야 한다.

  ③ 일비는 여행일수에 따라 지급하되, 공무용 차량을 이용하는 경우 등 인사혁신처장이 정하는 바에 따라 여행을 하는 경우에는 일비의 2분의 1을 지급한다.

  ④ 숙박비는 숙박하는 밤의 수에 따라 지급한다. 다만, 수로여행과 항공여행에는 숙박비를 지급하지 아니하되, 천재지변이나 그 밖의 부득이한 사유로 육지에서 숙박할 필요가 있는 경우에는 숙박비를 지급한다.

  ⑤ 식비는 여행일수에 따라 지급한다. 다만, 수로여행과 항공여행에는 따로 식비가 필요한 경우에만 식비를 지급한다.

  > 원문: 국가법령정보센터(law.go.kr) 공무원 여비 규정 [시행일 2026.07.01] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
  MD
  [ "unit-price-contract", :decree_content, "## 지방계약법 시행령 제79조·제80조 (단가계약)", <<~'MD' ],
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 지방계약법 시행령 제79조(단가계약)

  ① 법 제25조에 따라 단가계약을 체결할 수 있는 경우는 다음 각 호와 같다.
  1. 물품의 제조ㆍ구매ㆍ수리ㆍ가공
  2. 시설물의 보수ㆍ복구
  3. 전기ㆍ가스ㆍ수도의 공급
  4. 그 밖에 공급ㆍ사용ㆍ임차ㆍ매매 등의 계약

  ② 지방자치단체의 장 또는 계약담당자는 제1항에 따라 단가계약을 체결하려는 경우에는 입찰 전에 계약목적물의 특성, 계약수량 및 이행기간 등 필요한 기준 및 절차 등을 정하여야 하며, 이를 입찰에 참가하려는 자가 열람할 수 있도록 하여야 한다.

  ### 지방계약법 시행령 제80조(제3자를 위한 단가계약)

  ① 시ㆍ도지사는 법 제26조에 따른 제3자를 위한 단가계약을 체결하려는 경우 그의 관할구역에 있는 시ㆍ군ㆍ구에서 공통적으로 필요한 물품(이하 “수요물품”이라 한다)의 계약상대자를 선정한다. 다만, 「조달사업에 관한 법률」 제12조 제1항에 따라 조달청장이 이미 단가계약을 체결한 품목에 대해서는 그러하지 아니하다.

  ② 시ㆍ도지사는 제1항에 따라 제3자를 위한 단가계약을 체결하였을 때에는 그 단가계약 체결 현황을 시장ㆍ군수ㆍ구청장(자치구의 구청장을 말한다. 이하 같다)에게 통보하여야 한다.

  ③ 시장ㆍ군수ㆍ구청장은 제2항에 따라 해당 시ㆍ도지사로부터 수요물품의 단가계약 체결 현황을 통보받은 때에는 특별한 사유가 없으면 단가계약으로 체결된 수요물품을 구매하여야 한다.

  ④ 제1항에 따라 제3자를 위한 단가계약을 체결하기 위하여 필요한 사항은 시ㆍ도지사가 정한다.

  > 원문: 국가법령정보센터(law.go.kr) 지방계약법 시행령 [시행일 2026.06.03] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
  MD
  [ "vehicle-travel-allowance", :decree_content, "## 공무원여비규정 (자동차 운임)", <<~'MD' ]
  ## 관련 조문 원문

  이 탭은 법령 원문만 싣습니다. 종전에 이 자리에 있던 조문 요약·표는 원문과 일치하지 않아 원문으로 교체했습니다(2026-09-17 검증). 실무 해설은 해설 탭을 참고하세요.

  ### 공무원 여비 규정 제9조(운임의 구분)

  ① 운임은 철도운임ㆍ선박운임ㆍ항공운임ㆍ자동차운임으로 구분하되, 철도운임은 철도여행에, 선박운임은 수로(水路)여행에, 항공운임은 항공여행에, 자동차운임은 철도 외의 육로여행에 각각 지급한다.

  ② 국외 여행의 경우 제1항의 운임에는 통행세를 포함한다.

  ### 공무원 여비 규정 제13조(자동차운임의 지급)

  ① 국내 자동차운임은 별표 2에 따라 지급한다.

  ② 국외 자동차운임은 실비로 지급한다.

  > 원문: 국가법령정보센터(law.go.kr) 공무원 여비 규정 [시행일 2026.07.01] — 2026-09-17 대조. 개정 연혁 표기는 생략했습니다.
  MD
]

dry_run = ENV["DRY_RUN"] == "1"
changed = 0

ActiveRecord::Base.transaction do
  replacements.each do |slug, column, fingerprint, text|
    topic = Topic.find_by!(slug: slug)
    current = topic.public_send(column).to_s
    next if current == text

    raise "FIELD_CHANGED_SINCE_AUDIT #{slug}/#{column}" unless current.lstrip.start_with?(fingerprint)

    topic.update_columns(column => text, updated_at: Time.current) unless dry_run
    changed += 1
  end
  puts "  [g36-articles-p2] #{dry_run ? 'DRY_RUN ' : ''}changes=#{changed}"
  raise ActiveRecord::Rollback if dry_run
end
